import Foundation

public enum SubjectKind: String, CaseIterable, Codable, Sendable {
    case pinyin  = "pinyin"
    case math    = "math"
    case english = "english"

    public var title: String {
        switch self {
        case .pinyin:  return "🍲 拼音料理屋"
        case .math:    return "🧁 数学烘焙坊"
        case .english: return "🧃 英语饮品吧"
        }
    }

    public var shortTitle: String {
        switch self {
        case .pinyin:  return "语文拼音"
        case .math:    return "沪教数学"
        case .english: return "牛津英语"
        }
    }

    public var textbookSubtitle: String {
        switch self {
        case .pinyin:  return "沪教版一年级汉语拼音与识字（9大关卡 · 443字词）"
        case .math:    return "沪教版一年级数学上/下册（10大烘焙主题 · 468道真题+可视化教具）"
        case .english: return "沪教牛津上海版一年级英语（11大鲜果特调单元 · 223道听说拼句题）"
        }
    }

    public var themeHex: String {
        switch self {
        case .pinyin:  return "#F07D2E"
        case .math:    return "#E05385"
        case .english: return "#2FB380"
        }
    }
}

public struct CurriculumQuestion: Codable, Identifiable, Equatable, Sendable {
    public let id: String
    public let topicId: String
    public let difficulty: String
    public let type: String // "numeric", "choice", "sentence"
    public let prompt: String
    public let englishAudio: String?
    public let options: [String]
    public let answer: String
    public let explanation: String
    public let verify: String
}

public struct MathStageDefinition: Identifiable, Sendable {
    public let id: Int
    public let name: String
    public let subtitle: String
    public let semesterTag: String
    public let tip: String
    public let topicPrefixes: [String]
    public let dessertIds: [String]
}

public struct BakeryDessert: Identifiable, Equatable, Sendable {
    public let id: String
    public let emoji: String
    public let name: String
    public let stageId: Int
    public let mathSecret: String
}

public struct EnglishStageDefinition: Identifiable, Sendable {
    public let id: Int
    public let unitCode: String
    public let name: String
    public let subtitle: String
    public let topicWords: [String]
    public let keySentences: [String]
    public let topicPrefixes: [String]
}

public struct EnglishFlashcard: Identifiable, Equatable, Sendable {
    public var id: String { word }
    public let word: String
    public let emoji: String
    public let chinese: String
    public let example: String
    public let exampleCn: String
    public let unitName: String
}

