d": "hjm_g1a_u4_l5", "difficulty": "hard", "type": "numeric", "prompt": "□ + 2 - 1 = 8，□里填几？", "englishAudio": null, "options": [], "answer": "7", "explanation": "倒着推：8+1=9，9-2=7，所以□里填 7。", "verify": "8+1-2"}, {"id": "hjm_g1a_u4_l6_q1", "topicId": "hjm_g1a_u4_l6", "difficulty": "basic", "type": "numeric", "prompt": "10 的游戏：3 的好朋友是几？（和 3 加起来是 10）", "englishAudio": null, "options": [], "answer": "7", "explanation": "3+7=10，所以 3 的好朋友是 7。", "verify": "10-3"}, {"id": "hjm_g1a_u4_l6_q2", "topicId": "hjm_g1a_u4_l6", "difficulty": "medium", "type": "choice", "prompt": "10 的游戏：下面哪一对加起来是 10？", "englishAudio": null, "options": ["4 和 5", "6 和 4", "7 和 2"], "answer": "6 和 4", "explanation": "4+5=9，6+4=10，7+2=9，所以加起来是 10 的是 6 和 4。", "verify": ""}, {"id": "hjm_g1a_u4_l6_q3", "topicId": "hjm_g1a_u4_l6", "difficulty": "hard", "type": "numeric", "prompt": "10 的游戏：□ + □ = 10，两个□里填的数相同，是几？", "englishAudio": null, "options": [], "answer": "5", "explanation": "5+5=10，所以两个□里都填 5。容易错的是想成 10。", "verify": "10-5"}, {"id": "hjm_g1a_u4_l7_q1", "topicId": "hjm_g1a_u4_l7", "difficulty": "basic", "type": "numeric", "prompt": "2 + 3 + 4 = ？", "englishAudio": null, "options": [], "answer": "9", "explanation": "按顺序算：2+3=5，5+4=9。", "verify": "2+3+4"}, {"id": "hjm_g1a_u4_l7_q2", "topicId": "hjm_g1a_u4_l7", "difficulty": "medium", "type": "numeric", "prompt": "9 - 2 - 3 = ？", "englishAudio": null, "options": [], "answer": "4", "explanation": "按顺序算：9-2=7，7-3=4。", "verify": "9-2-3"}, {"id": "hjm_g1a_u4_l7_q3", "topicId": "hjm_g1a_u4_l7", "difficulty": "hard", "type": "numeric", "prompt": "小明有 10 元，买铅笔花了 2 元，买橡皮花了 3 元，还剩几元？", "englishAudio": null, "options": [], "answer": "5", "explanation": "先算 10-2=8，再算 8-3=5，还剩 5 元。", "verify": "10-2-3"}, {"id": "hjm_g1a_u4_l8_q1", "topicId": "hjm_g1a_u4_l8", "difficulty": "basic", "type": "numeric", "prompt": "3 + 5 - 2 = ？", "englishAudio": null, "options": [], "answer": "6", "explanation": "按顺序算：3+5=8，8-2=6。", "verify": "3+5-2"}, {"id": "hjm_g1a_u4_l8_q2", "topicId": "hjm_g1a_u4_l8", "difficulty": "medium", "type": "numeric", "prompt": "8 - 3 + 2 = ？", "englishAudio": null, "options": [], "answer": "7", "explanation": "按顺序算：8-3=5，5+2=7。", "verify": "8-3+2"}, {"id": "hjm_g1a_u4_l8_q3", "topicId": "hjm_g1a_u4_l8", "difficulty": "hard", "type": "choice", "prompt": "下面哪个算式的结果最大？", "englishAudio": null, "options": ["5+2-1", "9-4+1", "3+3+3"], "answer": "3+3+3", "explanation": "分别算出 5+2-1=6，9-4+1=6，3+3+3=9，最大的是 3+3+3。", "verify": ""}, {"id": "hjm_g1a_u5_l1_q1", "topicId": "hjm_g1a_u5_l1", "difficulty": "basic", "type": "numeric", "prompt": "1 个十和 3 个一合起来是几？", "englishAudio": null, "options": [], "answer": "13", "explanation": "1 个十是 10，再加 3 个一，就是 13。", "verify": "10+3"}, {"id": "hjm_g1a_u5_l1_q2", "topicId": "hjm_g1a_u5_l1", "difficulty": "medium", "type": "choice", "prompt": "15 里面有几个十和几个一？", "englishAudio": null, "options": ["1 个十和 5 个一", "5 个十和 1 个一", "1 个十和 15 个一"], "answer": "1 个十和 5 个一", "explanation": "15 = 10 + 5，所以是 1 个十和 5 个一。", "verify": ""}, {"id": "hjm_g1a_u5_l1_q3", "topicId": "hjm_g1a_u5_l1", "difficulty": "hard", "type": "numeric", "prompt": "一个数由 1 个十和 8 个一组成，它比 15 大几？", "englishAudio": null, "options": [], "answer": "3", "explanation": "这个数是 18，18-15=3，所以比 15 大 3。", "verify": "18-15"}, {"id": "hjm_g1a_u5_l2_q1", "topicId": "hjm_g1a_u5_l2", "difficulty": "basic", "type": "numeric", "prompt": "13 就是十和几？（填几）", "englishAudio": null, "options": [], "answer": "3", "explanation": "13 = 10 + 3，所以十几就是十和 3。", "verify": "13-10"}, {"id": "hjm_g1a_u5_l2_q2", "topicId": "hjm_g1a_u5_l2", "difficulty": "medium", "type": "choice", "prompt": "下面哪个数是 1 个十和 6 个一组成的？", "englishAudio": null, "options": ["61", "16", "6"], "answer": "16", "explanation": "1 个十和 6 个一组成 16。容易错的是写成 61，那是 6 个十和 1 个一。", "verify": ""}, {"id": "hjm_g1a_u5_l2_q3", "topicId": "hjm_g1a_u5_l2", "difficulty": "hard", "type": "numeric", "prompt": "17 减去 10 是几？再减去 2 是几？（填最后的结果）", "englishAudio": null, "options": [], "answer": "5", "explanation": "先算 17-10=7，再算 7-2=5，最后的结果是 5。", "verify": "17-10-2"}, {"id": "hjm_g1a_u5_l3_q1", "topicId": "hjm_g1a_u5_l3", "difficulty": "basic", "type": "numeric", "prompt": "11、12、13、□、15，□里填几？", "englishAudio": null, "options": [], "answer": "14", "explanation": "按顺序数，13 后面是 14，14 后面是 15。", "verify": ""}, {"id": "hjm_g1a_u5_l3_q2", "topicId": "hjm_g1a_u5_l3", "difficulty": "medium", "type": "choice", "prompt": "把 19、12、17 按从大到小的顺序排，排在最前面的是几？", "englishAudio": null, "options": ["19", "17", "12"], "answer": "19", "explanation": "19 > 17 > 12，所以从大到小排最前面的是 19。", "verify": ""}, {"id": "hjm_g1a_u5_l3_q3", "topicId": "hjm_g1a_u5_l3", "difficulty": "hard", "type": "numeric", "prompt": "18、16、□、12，□里填几？", "englishAudio": null, "options": [], "answer": "14", "explanation": "每次少 2：18、16、14、12，所以□里填 14。", "verify": ""}, {"id": "hjm_g1a_u6_l1_q1", "topicId": "hjm_g1a_u6_l1", "difficulty": "basic", "type": "numeric", "prompt": "13 + 4 = ？", "englishAudio": null, "options": [], "answer": "17", "explanation": "13+4，把 3 和 4 先加得 7，再加 10，得 17。", "verify": "13+4"}, {"id": "hjm_g1a_u6_l1_q2", "topicId": "hjm_g1a_u6_l1", "difficulty": "medium", "type": "numeric", "prompt": "18 - 5 = ？", "englishAudio": null, "options": [], "answer": "13", "explanation": "18-5，把 8 和 5 先减得 3，再加 10，得 13。", "verify": "18-5"}, {"id": "hjm_g1a_u6_l1_q3", "topicId": "hjm_g1a_u6_l1", "difficulty": "hard", "type": "numeric", "prompt": "一根绳子长 16 米，剪去 3 米，又接上 2 米，现在长几米？", "englishAudio": null, "options": [], "answer": "15", "explanation": "先算 16-3=13，再算 13+2=15，现在长 15 米。", "verify": "16-3+2"}, {"id": "hjm_g1a_u6_l2_q1", "topicId": "hjm_g1a_u6_l2", "difficulty": "basic", "type": "numeric", "prompt": "9 + 3 = ？", "englishAudio": null, "options": [], "answer": "12", "explanation": "9 再添 3 就是 12。", "verify": "9+3"}, {"id": "hjm_g1a_u6_l2_q2", "topicId": "hjm_g1a_u6_l2", "difficulty": "medium", "type": "choice", "prompt": "8 + 5 = ？", "englishAudio": null, "options": ["12", "13", "14"], "answer": "13", "explanation": "8+2=10，10+3=13，所以 8+5=13。", "verify": ""}, {"id": "hjm_g1a_u6_l2_q3", "topicId": "hjm_g1a_u6_l2", "difficulty": "hard", "type": "numeric", "prompt": "小明有 7 颗糖，妈妈又给他 8 颗，他一共有几颗？（用凑十法想一想）", "englishAudio": null, "options": [], "answer": "15", "explanation": "凑十法：7+3=10，10+5=15，所以一共 15 颗。", "verify": "7+8"}, {"id": "hjm_g1a_u6_l3_q1", "topicId": "hjm_g1a_u6_l3", "difficulty": "basic", "type": "numeric", "prompt": "做加法表：5 + 5 = ？", "englishAudio": null, "options": [], "answer": "10", "explanation": "5+5=10。", "verify": "5+5"}, {"id": "hjm_g1a_u6_l3_q2", "topicId": "hjm_g1a_u6_l3", "difficulty": "medium", "type": "choice", "prompt": "加法表中，和是 11 的一组是？", "englishAudio": null, "options": ["5+5", "6+5", "7+3"], "answer": "6+5", "explanation": "5+5=10，6+5=11，7+3=10，所以和是 11 的是 6+5。", "verify": ""}, {"id": "hjm_g1a_u6_l3_q3", "topicId": "hjm_g1a_u6_l3", "difficulty": "hard", "type": "numeric", "prompt": "加法表中，6 + 7 = 13，那么 7 + 6 = ？", "englishAudio": null, "options": [], "answer": "13", "explanation": "加数交换位置，和不变，所以 7+6 也是 13。容易错的是以为要重新算。", "verify": "7+6"}, {"id": "hjm_g1b_u1_l1_q1", "topicId": "hjm_g1b_u1_l1", "difficulty": "basic", "type": "numeric", "prompt": "13-4=？", "englishAudio": null, "options": [], "answer": "9", "explanation": "用破十法：13分成10和3，先算10-4=6，再算6+3=9。", "verify": "13-4"}, {"id": "hjm_g1b_u1_l1_q2", "topicId": "hjm_g1b_u1_l1", "difficulty": "medium", "type": "choice", "prompt": "小明有15颗糖，吃了7颗，还剩几颗糖？", "englishAudio": null, "options": ["8", "9", "7"], "answer": "8", "explanation": "15-7用破十法：15分成10和5，10-7=3，3+5=8，所以还剩8颗糖。", "verify": ""}, {"id": "hjm_g1b_u1_l1_q3", "topicId": "hjm_g1b_u1_l1", "difficulty": "hard", "type": "numeric", "prompt": "妈妈买了14个苹果，吃了5个，又买了6个，现在一共有几个苹果？", "englishAudio": null, "options": [], "answer": "15", "explanation": "先算14-5=9，再算9+6=15，所以现在有15个苹果。", "verify": "14-5+6"}, {"id": "hjm_g1b_u1_l2_q1", "topicId": "hjm_g1b_u1_l2", "difficulty": "basic", "type": "numeric", "prompt": "11-3=？", "englishAudio": null, "options": [], "answer": "8", "explanation": "11-3用破十法：11分成10和1，10-3=7，7+1=8。", "verify": "11-3"}, {"id": "hjm_g1b_u1_l2_q2", "topicId": "hjm_g1b_u1_l2", "difficulty": "medium", "type": "choice", "prompt": "下面哪道算式的得数是9？", "englishAudio": null, "options": ["15-6", "14-6", "16-6"], "answer": "15-6", "explanation": "15-6=9，14-6=8，16-6=10，所以得数是9的是15-6。", "verify": ""}, {"id": "hjm_g1b_u1_l2_q3", "topicId": "hjm_g1b_u1_l2", "difficulty": "hard", "type": "numeric", "prompt": "已知12-7=5，那么13-8的得数是几？", "englishAudio": null, "options": [], "answer": "5", "explanation": "12-7=5这一组里，被减数和减数同时增加1，得数不变：13-8和12-7是一组的，所以得数也是5。", "verify": "13-8"}, {"id": "hjm_g1b_u1_l3_q1", "topicId": "hjm_g1b_u1_l3", "difficulty": "basic", "type": "numeric", "prompt": "树上有12只鸟，飞走了4只，还剩几只鸟？", "englishAudio": null, "options": [], "answer": "8", "explanation": "树上的鸟飞走了4只，求还剩几只用减法：12-4=8。", "verify": "12-4"}, {"id": "hjm_g1b_u1_l3_q2", "topicId": "hjm_g1b_u1_l3", "difficulty": "medium", "type": "choice", "prompt": "小红有9支铅笔，妈妈又买来7支，她一共有几支铅笔？", "englishAudio": null, "options": ["15", "16", "17"], "answer": "16", "explanation": "原来9支，又买来7支，求一共用加法：9+7=16。", "verify": ""}, {"id": "hjm_g1b_u1_l3_q3", "topicId": "hjm_g1b_u1_l3", "difficulty": "hard", "type": "numeric", "prompt": "小方有13块积木，送给弟弟5块，又买来4块，现在有几块积木？", "englishAudio": null, "options": [], "answer": "12", "explanation": "先算送出后剩下13-5=8块，再算买来后8+4=12块。", "verify": "13-5+4"}, {"id": "hjm_g1b_u1_l4_q1", "topicId": "hjm_g1b_u1_l4", "difficulty": "basic", "type": "choice", "prompt": "用3、8、11组一道加法算式，正确的是哪道？", "englishAudio": null, "options": ["3+8=11", "8+11=3", "3+11=8"], "answer": "3+8=11", "explanation": "3和8是两个加数，11是和，加法算式是3+8=11。", "verify": ""}, {"id": "hjm_g1b_u1_l4_q2", "topicId": "hjm_g1b_u1_l4", "difficulty": "medium", "type": "choice", "prompt": "已知13-4=9，用4、9、13还能组成哪道加法算式？", "englishAudio": null, "options": ["4+9=13", "9+13=4", "4+13=9"], "answer": "4+9=13", "explanation": "13-4=9这一组数里，4和9是两个部分数，13是总数，所以加法算式是4+9=13。", "verify": ""}, {"id": "hjm_g1b_u1_l4_q3", "topicId": "hjm_g1b_u1_l4", "difficulty": "hard", "type": "numeric", "prompt": "已知17-8=9，用8、9、17组成的另一道减法算式的得数是几？", "englishAudio": null, "options": [], "answer": "8", "explanation": "8、9、17这一组数里，已知17-8=9，交换两个部分数的位置，另一道减法算式是17-9=8。", "verify": "17-9"}, {"id": "hjm_g1b_u2_l1_q1", "topicId": "hjm_g1b_u2_l1", "difficulty": "basic", "type": "numeric", "prompt": "从48往后数两个数是几？", "englishAudio": null, "options": [], "answer": "50", "explanation": "48往后数：49是第1个，50是第2个。", "verify": "48+2"}, {"id": "hjm_g1b_u2_l1_q2", "topicId": "hjm_g1b_u2_l1", "difficulty": "medium", "type": "choice", "prompt": "59后面第3个数是几？", "englishAudio": null, "options": ["61", "62", "63"], "answer": "62", "explanation": "59后面依次是60、61、62，第3个是62。", "verify": ""}, {"id": "hjm_g1b_u2_l1_q3", "topicId": "hjm_g1b_u2_l1", "difficulty": "hard", "type": "numeric", "prompt": "从35开始，每次多数5，数3次后是几？", "englishAudio": null, "options": [], "answer": "50", "explanation": "每次多数5，数3次就是多3个5：35+5+5+5=50。", "verify": "35+5+5+5"}, {"id": "hjm_g1b_u2_l2_q1", "topicId": "hjm_g1b_u2_l2", "difficulty": "basic", "type": "choice", "prompt": "“六十三”写作几？", "englishAudio": null, "options": ["36", "63", "603"], "answer": "63", "explanation": "六十三就是6个十和3个一，写作63。", "verify": ""}, {"id": "hjm_g1b_u2_l2_q2", "topicId": "hjm_g1b_u2_l2", "difficulty": "medium", "type": "numeric", "prompt": "由7个十和2个一组成的数是几？", "englishAudio": null, "options": [], "answer": "72", "explanation": "7个十是70，2个一是2，合起来是72。", "verify": ""}, {"id": "hjm_g1b_u2_l2_q3", "topicId": "hjm_g1b_u2_l2", "difficulty": "hard", "type": "numeric", "prompt": "一个两位数，十位是8，个位比十位少3，这个数是几？", "englishAudio": null, "options": [], "answer": "85", "explanation": "十位是8，个位比十位少3，个位就是8-3=5，这个数是85。", "verify": ""}, {"id": "hjm_g1b_u2_l3_q1", "topicId": "hjm_g1b_u2_l3", "difficulty": "basic", "type": "numeric", "prompt": "53里面有几个十？", "englishAudio": null, "options": [], "answer": "5", "explanation": "53的十位是5，表示5个十。", "verify": ""}, {"id": "hjm_g1b_u2_l3_q2", "topicId": "hjm_g1b_u2_l3", "difficulty": "medium", "type": "choice", "prompt": "6个十和8个一组成的数是几？", "englishAudio": null, "options": ["68", "86", "608"], "answer": "68", "explanation": "6个十是60，8个一是8，合起来是68。", "verify": ""}, {"id": "hjm_g1b_u2_l3_q3", "topicId": "hjm_g1b_u2_l3", "difficulty": "hard", "type": "numeric", "prompt": "一个数由3个十和9个一组成，再添上1个一是几？", "englishAudio": null, "options": [], "answer": "40", "explanation": "3个十和9个一组成的数是39，再添上1个一就是40。", "verify": "39+1"}, {"id": "hjm_g1b_u2_l4_q1", "topicId": "hjm_g1b_u2_l4", "difficulty": "basic", "type": "choice", "prompt": "46在几十和几十之间？", "englishAudio": null, "options": ["40和50", "30和40", "50和60"], "answer": "40和50", "explanation": "46比40大、比50小，所以46在40和50之间。", "verify": ""}, {"id": "hjm_g1b_u2_l4_q2", "topicId": "hjm_g1b_u2_l4", "difficulty": "medium", "type": "numeric", "prompt": "在数轴上，58前面第2个数是几？", "englishAudio": null, "options": [], "answer": "56", "explanation": "58前面第1个数是57，第2个数是56。", "verify": "58-2"}, {"id": "hjm_g1b_u2_l4_q3", "topicId": "hjm_g1b_u2_l4", "difficulty": "hard", "type": "choice", "prompt": "哪个数离60最近？", "englishAudio": null, "options": ["55", "64", "59"], "answer": "59", "explanation": "55离60差5，64离60差4，59离60只差1，所以59离60最近。", "verify": ""}, {"id": "hjm_g1b_u2_l5_q1", "topicId": "hjm_g1b_u2_l5", "difficulty": "basic", "type": "numeric", "prompt": "10个十是几？", "englishAudio": null, "options": [], "answer": "100", "explanation": "1个十是10，10个十就是100。", "verify": ""}, {"id": "hjm_g1b_u2_l5_q2", "topicId": "hjm_g1b_u2_l5", "difficulty": "medium", "type": "choice", "prompt": "100比99大几？", "englishAudio": null, "options": ["1", "10", "100"], "answer": "1", "explanation": "100比99多1，因为99再添1就是100。", "verify": ""}, {"id": "hjm_g1b_u2_l5_q3", "topicId": "hjm_g1b_u2_l5", "difficulty": "hard", "type": "numeric", "prompt": "一个两位数加上1就变成100，这个两位数是几？", "englishAudio": null, "options": [], "answer": "99", "explanation": "99加上1就满100，所以这个两位数是99。", "verify": ""}, {"id": "hjm_g1b_u2_l6_q1", "topicId": "hjm_g1b_u2_l6", "difficulty": "basic", "type": "choice", "prompt": "54和45哪个大？", "englishAudio": null, "options": ["54", "45", "一样大"], "answer": "54", "explanation": "比十位：54十位是5，45十位是4，5比4大，所以54大。", "verify": ""}, {"id": "hjm_g1b_u2_l6_q2", "topicId": "hjm_g1b_u2_l6", "difficulty": "medium", "type": "numeric", "prompt": "在67、76、66中最大的数是几？", "englishAudio": null, "options": [], "answer": "76", "explanation": "67、76、66的十位分别是6、7、6，十位7最大，所以76最大。", "verify": ""}, {"id": "hjm_g1b_u2_l6_q3", "topicId": "hjm_g1b_u2_l6", "difficulty": "hard", "type": "choice", "prompt": "用5、0、8组成最大的两位数是几？", "englishAudio": null, "options": ["85", "80", "58"], "answer": "85", "explanation": "最大的两位数要十位尽量大：十位用8，个位用5，是85；80的个位是0，比85小。", "verify": ""}, {"id": "hjm_g1b_u2_l7_q1", "topicId": "hjm_g1b_u2_l7", "difficulty": "basic", "type": "numeric", "prompt": "39相邻的两个数中较大的一个是几？", "englishAudio": null, "options": [], "answer": "40", "explanation": "39相邻的两个数是38和40，其中较大的是40。", "verify": ""}, {"id": "hjm_g1b_u2_l7_q2", "topicId": "hjm_g1b_u2_l7", "difficulty": "medium", "type": "choice", "prompt": "与70相邻的两个数是几和几？", "englishAudio": null, "options": ["69和71", "70和71", "69和70"], "answer": "69和71", "explanation": "相邻的数就是前后各1的数：70前面是69，后面是71。", "verify": ""}, {"id": "hjm_g1b_u2_l7_q3", "topicId": "hjm_g1b_u2_l7", "difficulty": "hard", "type": "numeric", "prompt": "一个数，它前面的数是59，后面的数是61，这个数是几？", "englishAudio": null, "options": [], "answer": "60", "explanation": "前面的数是59，后面的数是61，夹在中间的数就是60。", "verify": ""}, {"id": "hjm_g1b_u3_l1_q1", "topicId": "hjm_g1b_u3_l1", "difficulty": "basic", "type": "choice", "prompt": "钟面上时针指着8，分针指着12，现在是几时？", "englishAudio": null, "options": ["8时", "12时", "8时半"], "answer": "8时", "explanation": "分针指着12表示整时，时针指着几就是几时：时针指着8，就是8时。", "verify": ""}, {"id": "hjm_g1b_u3_l1_q2", "topicId": "hjm_g1b_u3_l1", "difficulty": "medium", "type": "numeric", "prompt": "小明7时起床，这时分针指着12，时针指着几？", "englishAudio": null, "options": [], "answer": "7", "explanation": "整时的时候分针指着12，时针指着几就是几时：7时起床，时针指着7。", "verify": ""}, {"id": "hjm_g1b_u3_l1_q3", "topicId": "hjm_g1b_u3_l1", "difficulty": "hard", "type": "numeric", "prompt": "钟面上现在是9时，2小时后是几时？", "englishAudio": null, "options": [], "answer": "11", "explanation": "现在是9时，2小时后就是9+2=11时。", "verify": "9+2"}, {"id": "hjm_g1b_u3_l2_q1", "topicId": "hjm_g1b_u3_l2", "difficulty": "basic", "type": "choice", "prompt": "钟面上时针在6和7之间，分针指着6，是几时半？", "englishAudio": null, "options": ["6时半", "7时半", "6时"], "answer": "6时半", "explanation": "分针指着6表示半时，时针在6和7之间表示刚过6时，就是6时半。", "verify": ""}, {"id": "hjm_g1b_u3_l2_q2", "topicId": "hjm_g1b_u3_l2", "difficulty": "medium", "type": "numeric", "prompt": "8时半再过半小时是几时？", "englishAudio": null, "options": [], "answer": "9", "explanation": "8时半再过半小时，分针走半圈，就到了9时。", "verify": ""}, {"id": "hjm_g1b_u3_l2_q3", "topicId": "hjm_g1b_u3_l2", "difficulty": "hard", "type": "choice", "prompt": "小红4时半开始画画，画了1小时，结束时是几时半？", "englishAudio": null, "options": ["5时半", "4时半", "5时"], "answer": "5时半", "explanation": "4时半开始，画了1小时，时针走过1大格，就是5时半。", "verify": ""}, {"id": "hjm_g1b_u4_l1_q1", "topicId": "hjm_g1b_u4_l1", "difficulty": "basic", "type": "numeric", "prompt": "34+25=？", "englishAudio": null, "options": [], "answer": "59", "explanation": "34+25，十位加十位是50，个位加个位是9，合起来是59，没有进位。", "verify": "34+25"}, {"id": "hjm_g1b_u4_l1_q2", "topicId": "hjm_g1b_u4_l1", "difficulty": "medium", "type": "choice", "prompt": "52+30的得数是几？", "englishAudio": null, "options": ["82", "62", "72"], "answer": "82", "explanation": "52+30，十位5+3=8，个位2+0=2，合起来是82。", "verify": ""}, {"id": "hjm_g1b_u4_l1_q3", "topicId": "hjm_g1b_u4_l1", "difficulty": "hard", "type": "numeric", "prompt": "43+25+10=？", "englishAudio": null, "options": [], "answer": "78", "explanation": "先算43+25=68，再算68+10=78。", "verify": "43+25+10"}, {"id": "hjm_g1b_u4_l2_q1", "topicId": "hjm_g1b_u4_l2", "difficulty": "basic", "type": "numeric", "prompt": "48+5=？", "englishAudio": null, "options": [], "answer": "53", "explanation": "48+5，个位8+5=13，满十进1，十位变成5，个位剩3，是53。", "verify": "48+5"}, {"id": "hjm_g1b_u4_l2_q2", "topicId": "hjm_g1b_u4_l2", "difficulty": "medium", "type": "choice", "prompt": "36+27的得数是几？", "englishAudio": null, "options": ["63", "53", "73"], "answer": "63", "explanation": "36+27，个位6+7=13，写3进1，十位3+2+1=6，是63。", "verify": ""}, {"id": "hjm_g1b_u4_l2_q3", "topicId": "hjm_g1b_u4_l2", "difficulty": "hard", "type": "numeric", "prompt": "59+16+8=？", "englishAudio": null, "options": [], "answer": "83", "explanation": "先算59+16=75，再算75+8=83。", "verify": "59+16+8"}, {"id": "hjm_g1b_u4_l3_q1", "topicId": "hjm_g1b_u4_l3", "difficulty": "basic", "type": "numeric", "prompt": "12+13+14=？", "englishAudio": null, "options": [], "answer": "39", "explanation": "连加从左往右算：12+13=25，25+14=39。", "verify": "12+13+14"}, {"id": "hjm_g1b_u4_l3_q2", "topicId": "hjm_g1b_u4_l3", "difficulty": "medium", "type": "choice", "prompt": "25+11+12的得数是几？", "englishAudio": null, "options": ["48", "38", "58"], "answer": "48", "explanation": "25+11=36，36+12=48。", "verify": ""}, {"id": "hjm_g1b_u4_l3_q3", "topicId": "hjm_g1b_u4_l3", "difficulty": "hard", "type": "numeric", "prompt": "小队第一天收集24个瓶盖，第二天18个，第三天15个，一共收集几个瓶盖？", "englishAudio": null, "options": [], "answer": "57", "explanation": "三天合起来用连加：24+18=42，42+15=57。", "verify": "24+18+15"}, {"id": "hjm_g1b_u5_l1_q1", "topicId": "hjm_g1b_u5_l1", "difficulty": "basic", "type": "choice", "prompt": "一支铅笔和一根跳绳比，谁长？", "englishAudio": null, "options": ["铅笔", "跳绳", "一样长"], "answer": "跳绳", "explanation": "跳绳比铅笔长得多，一眼就能看出来。", "verify": ""}, {"id": "hjm_g1b_u5_l1_q2", "topicId": "hjm_g1b_u5_l1", "difficulty": "medium", "type": "choice", "prompt": "红绳比蓝绳长，蓝绳比绿绳长，最长的是哪条绳？", "englishAudio": null, "options": ["红绳", "蓝绳", "绿绳"], "answer": "红绳", "explanation": "红绳比蓝绳长，蓝绳比绿绳长，所以红绳最长。", "verify": ""}, {"id": "hjm_g1b_u5_l1_q3", "topicId": "hjm_g1b_u5_l1", "difficulty": "hard", "type": "choice", "prompt": "小刀比橡皮长，橡皮比回形针长，把三样从长到短排，排在中间的是什么？", "englishAudio": null, "options": ["橡皮", "小刀", "回形针"], "answer": "橡皮", "explanation": "从长到短排是小刀、橡皮、回形针，排在中间的是橡皮。", "verify": ""}, {"id": "hjm_g1b_u5_l2_q1", "topicId": "hjm_g1b_u5_l2", "difficulty": "basic", "type": "numeric", "prompt": "用直尺量一支铅笔，左端对准0刻度，右端对准7厘米，这支铅笔长几厘米？", "englishAudio": null, "options": [], "answer": "7", "explanation": "左端对准0刻度，右端对准7厘米，铅笔长就是7厘米。", "verify": ""}, {"id": "hjm_g1b_u5_l2_q2", "topicId": "hjm_g1b_u5_l2", "difficulty": "medium", "type": "choice", "prompt": "量一本书的长，用什么单位比较合适？", "englishAudio": null, "options": ["厘米", "米", "克"], "answer": "厘米", "explanation": "书的长度只有几十厘米，用厘米量正好；用米量的话还不到1米，不方便读数；克是称重量的单位，不是长度单位。", "verify": ""}, {"id": "hjm_g1b_u5_l2_q3", "topicId": "hjm_g1b_u5_l2", "difficulty": "hard", "type": "numeric", "prompt": "一条绳子长15厘米，剪去6厘米，还剩几厘米？", "englishAudio": null, "options": [], "answer": "9", "explanation": "绳子原来15厘米，剪去6厘米，求还剩用减法：15-6=9。", "verify": "15-6"}, {"id": "hjm_g1b_u5_l3_q1", "topicId": "hjm_g1b_u5_l3", "difficulty": "basic", "type": "choice", "prompt": "下面哪一项说的是线段？", "englishAudio": null, "options": ["直直的，两端有端点", "弯弯的，没有端点", "直直的，只有一端"], "answer": "直直的，两端有端点", "explanation": "线段是直直的，而且两端都有端点。", "verify": ""}, {"id": "hjm_g1b_u5_l3_q2", "topicId": "hjm_g1b_u5_l3", "difficulty": "medium", "type": "numeric", "prompt": "一条线段长8厘米，另一条比它长3厘米，另一条长几厘米？", "englishAudio": null, "options": [], "answer": "11", "explanation": "另一条比8厘米长3厘米，就是8+3=11厘米。", "verify": "8+3"}, {"id": "hjm_g1b_u5_l3_q3", "topicId": "hjm_g1b_u5_l3", "difficulty": "hard", "type": "numeric", "prompt": "一张长方形纸有几条线段做边？", "englishAudio": null, "options": [], "answer": "4", "explanation": "长方形有4条边，每条边都是一条线段，所以是4条。", "verify": ""}, {"id": "hjm_g1b_u6_l1_q1", "topicId": "hjm_g1b_u6_l1", "difficulty": "basic", "type": "choice", "prompt": "量课桌的长，用身体上的哪把“尺子”比较合适？", "englishAudio": null, "options": ["一拃", "一步", "一庹"], "answer": "一拃", "explanation": "课桌比较短，用一拃一拃地量正好；用一步量，步子太大不方便。", "verify": ""}, {"id": "hjm_g1b_u6_l1_q2", "topicId": "hjm_g1b_u6_l1", "difficulty": "medium", "type": "numeric", "prompt": "小明的一拃大约10厘米，3拃大约几厘米？", "englishAudio": null, "options": [], "answer": "30", "explanation": "1拃大约10厘米，3拃就是3个10厘米：10+10+10=30。", "verify": "10+10+10"}, {"id": "hjm_g1b_u6_l1_q3", "topicId": "hjm_g1b_u6_l1", "difficulty": "hard", "type": "numeric", "prompt": "小红一拃8厘米，她用拃量书桌，量了5拃，书桌大约长几厘米？", "englishAudio": null, "options": [], "answer": "40", "explanation": "1拃8厘米，5拃就是5个8厘米：8+8+8+8+8=40。", "verify": "8+8+8+8+8"}, {"id": "hjm_g1b_u6_l2_q1", "topicId": "hjm_g1b_u6_l2", "difficulty": "basic", "type": "numeric", "prompt": "小明量得自己一拃是9厘米，2拃大约几厘米？", "englishAudio": null, "options": [], "answer": "18", "explanation": "1拃9厘米，2拃就是2个9厘米：9+9=18。", "verify": "9+9"}, {"id": "hjm_g1b_u6_l2_q2", "topicId": "hjm_g1b_u6_l2", "difficulty": "medium", "type": "choice", "prompt": "量黑板的长度，适合用身体上的哪把“尺子”？", "englishAudio": null, "options": ["一庹", "一拃", "一步"], "answer": "一庹", "explanation": "黑板很长，用一拃量要量很多次；一庹张开手臂长，一量就够。", "verify": ""}, {"id": "hjm_g1b_u6_l2_q3", "topicId": "hjm_g1b_u6_l2", "difficulty": "hard", "type": "numeric", "prompt": "小方的步长大约25厘米，他走了4步，大约走了几厘米？", "englishAudio": null, "options": [], "answer": "100", "explanation": "1步大约25厘米，4步就是4个25厘米：25+25+25+25=100。", "verify": "25+25+25+25"}, {"id": "hjm_g1b_u6_l3_q1", "topicId": "hjm_g1b_u6_l3", "difficulty": "basic", "type": "numeric", "prompt": "从0米处挂第1面彩旗，每隔2米挂一面，第3面彩旗在几米处？", "englishAudio": null, "options": [], "answer": "4", "explanation": "从0米处挂第1面，每隔2米挂一面：第1面在0米，第2面在2米，第3面在4米。", "verify": "2+2"}, {"id": "hjm_g1b_u6_l3_q2", "topicId": "hjm_g1b_u6_l3", "difficulty": "medium", "type": "choice", "prompt": "一排彩旗按红、黄、红、黄的顺序排列，第7面是什么颜色？", "englishAudio": null, "options": ["红", "黄", "蓝"], "answer": "红", "explanation": "彩旗按红、黄、红、黄排列，第1、3、5、7面都是红色，第7面是红色。", "verify": ""}, {"id": "hjm_g1b_u6_l3_q3", "topicId": "hjm_g1b_u6_l3", "difficulty": "hard", "type": "numeric", "prompt": "教室长12米，每隔3米挂一面彩旗（两端都挂），一共挂几面？", "englishAudio": null, "options": [], "answer": "5", "explanation": "从0米起每3米一面：0米、3米、6米、9米、12米，数一数共5面。", "verify": ""}, {"id": "hjm_g1b_u7_l1_q1", "topicId": "hjm_g1b_u7_l1", "difficulty": "basic", "type": "choice", "prompt": "2、4、6、8，后面一个数是几？", "englishAudio": null, "options": ["9", "10", "11"], "answer": "10", "explanation": "2、4、6、8每次多2，下一个就是8+2=10。", "verify": ""}, {"id": "hjm_g1b_u7_l1_q2", "topicId": "hjm_g1b_u7_l1", "difficulty": "medium", "type": "numeric", "prompt": "5、10、15、20，后面一个数是几？", "englishAudio": null, "options": [], "answer": "25", "explanation": "5、10、15、20每次多5，下一个就是20+5=25。", "verify": "20+5"}, {"id": "hjm_g1b_u7_l1_q3", "topicId": "hjm_g1b_u7_l1", "difficulty": "hard", "type": "numeric", "prompt": "1、2、4、7、11，后面一个数是几？", "englishAudio": null, "options": [], "answer": "16", "explanation": "相邻两数相差1、2、3、4，每次多1，下一次相差5：11+5=16。", "verify": ""}, {"id": "hjm_g1b_u7_l2_q1", "topicId": "hjm_g1b_u7_l2", "difficulty": "basic", "type": "numeric", "prompt": "数墙最下面两块是3和5，它们上面的那块是几？", "englishAudio": null, "options": [], "answer": "8", "explanation": "数墙里，上面一块等于下面两块的和：3+5=8。", "verify": "3+5"}, {"id": "hjm_g1b_u7_l2_q2", "topicId": "hjm_g1b_u7_l2", "difficulty": "medium", "type": "numeric", "prompt": "数墙底层是3、4、5，顶层是几？", "englishAudio": null, "options": [], "answer": "16", "explanation": "底层3、4、5，中间层是3+4=7和4+5=9，顶层是7+9=16。", "verify": "7+9"}, {"id": "hjm_g1b_u7_l2_q3", "topicId": "hjm_g1b_u7_l2", "difficulty": "hard", "type": "choice", "prompt": "数墙顶层是20，中间一层有一块是12，另一块是几？", "englishAudio": null, "options": ["8", "12", "32"], "answer": "8", "explanation": "顶层20等于中间两块的和，一块是12，另一块就是20-12=8。", "verify": ""}, {"id": "hjm_g1a_u1_l1_q4", "topicId": "hjm_g1a_u1_l1", "difficulty": "medium", "type": "numeric", "prompt": "说一说：书架上有 6 本书，借出 2 本，又买来 4 本，现在有几本书？", "englishAudio": null, "options": [], "answer": "8", "explanation": "先算 6-2=4，再算 4+4=8，现在有 8 本书。借出要减，买来要加。", "verify": "6-2+4"}, {"id": "hjm_g1a_u1_l1_q5", "topicId": "hjm_g1a_u1_l1", "difficulty": "hard", "type": "numeric", "prompt": "说一说：小华有 4 块饼干，给弟弟 1 块，又给妹妹 1 块，还剩几块？", "englishAudio": null, "options": [], "answer": "2", "explanation": "给出去两次，要减两次：4-1-1=2。容易错的是只减一次，算成 3 块。", "verify": "4-1-1"}, {"id": "hjm_g1a_u1_l2_q4", "topicId": "hjm_g1a_u1_l2", "difficulty": "medium", "type": "numeric", "prompt": "玩一玩：拼图拼了 7 块，又拼 2 块，拆掉 1 块，还剩几块拼好的？", "englishAudio": null, "options": [], "answer": "8", "explanation": "先算 7+2=9，再算 9-1=8，还剩 8 块拼好的。", "verify": "7+2-1"}, {"id": "hjm_g1a_u1_l2_q5", "topicId": "hjm_g1a_u1_l2", "difficulty": "hard", "type": "numeric", "prompt": "玩一玩：玩捉迷藏，藏了 9 人，找到 4 人，又有 2 人自己跑出来，现在还藏着几人？", "englishAudio": null, "options": [], "answer": "3", "explanation": "找到的和自己跑出来的都要减：9-4-2=3。容易错的是忘了跑出来的 2 人。", "verify": "9-4-2"}, {"id": "hjm_g1a_u1_l3_q4", "topicId": "hjm_g1a_u1_l3", "difficulty": "medium", "type": "choice", "prompt": "认一认：下面哪个数比 8 小，又比 5 大？", "englishAudio": null, "options": ["6", "9", "4"], "answer": "6", "explanation": "比 8 小的数有 7、6、5……，比 5 大的数有 6、7、8……，两个条件都满足的是 6。", "verify": ""}, {"id": "hjm_g1a_u1_l3_q5", "topicId": "hjm_g1a_u1_l3", "difficulty": "hard", "type": "numeric", "prompt": "认一认：从 3 开始往后数，数到第 5 个数是几？", "englishAudio": null, "options": [], "answer": "7", "explanation": "3 是第 1 个，4 是第 2 个，5 是第 3 个，6 是第 4 个，7 是第 5 个。容易错的是从 3 往后多数 5 个，算成 8。", "verify": ""}, {"id": "hjm_g1a_u2_l1_q4", "topicId": "hjm_g1a_u2_l1", "difficulty": "medium", "type": "choice", "prompt": "认识立体图形：哪个图形可以立着放，又可以滚动？", "englishAudio": null, "options": ["圆柱", "正方体", "长方体"], "answer": "圆柱", "explanation": "圆柱底面平平的可以立着放，侧面弯弯的可以滚动；正方体和长方体只能立着放，不能滚。", "verify": ""}, {"id": "hjm_g1a_u2_l1_q5", "topicId": "hjm_g1a_u2_l1", "difficulty": "hard", "type": "numeric", "prompt": "认识立体图形：数一数，一个圆柱有几个面？", "englishAudio": null, "options": [], "answer": "3", "explanation": "圆柱有上面一个平平的圆面，下面一个平平的圆面，中间一个弯弯的面，一共 3 个面。容易错的是只数上下两个圆面，漏了侧面。", "verify": ""}, {"id": "hjm_g1a_u2_l2_q4", "topicId": "hjm_g1a_u2_l2", "difficulty": "medium", "type": "choice", "prompt": "认识平面图形：正方形有几条边、几个角？", "englishAudio": null, "options": ["4 条边，4 个角", "3 条边，3 个角", "4 条边，3 个角"], "answer": "4 条边，4 个角", "explanation": "正方形有上、下、左、右 4 条边，4 个角都是直直的角。", "verify": ""}, {"id": "hjm_g1a_u2_l2_q5", "topicId": "hjm_g1a_u2_l2", "difficulty": "hard", "type": "choice", "prompt": "认识平面图形：下面哪个图形不是平面图形？", "englishAudio": null, "options": ["三角形", "圆", "皮球"], "answer": "皮球", "explanation": "平面图形是平平的，三角形和圆都是平平的；皮球圆鼓鼓的，是立体图形。容易错的是看到皮球圆圆的就以为是圆形。", "verify": ""}, {"id": "hjm_g1a_u3_l1_q4", "topicId": "hjm_g1a_u3_l1", "difficulty": "medium", "type": "numeric", "prompt": "4 后面第二个数是几？", "englishAudio": null, "options": [], "answer": "6", "explanation": "4 后面是 5，5 后面是 6，所以 4 后面第二个数是 6。", "verify": ""}, {"id": "hjm_g1a_u3_l1_q5", "topicId": "hjm_g1a_u3_l1", "difficulty": "hard", "type": "numeric", "prompt": "把 2、5、1、4 按从小到大排，排在第 3 个的是几？", "englishAudio": null, "options": [], "answer": "4", "explanation": "从小到大排是 1、2、4、5，第 3 个是 4。容易错的是按原来的顺序数，第 3 个就数成了 1。", "verify": ""}, {"id": "hjm_g1a_u3_l2_q4", "topicId": "hjm_g1a_u3_l2", "difficulty": "medium", "type": "numeric", "prompt": "树上有 4 只鸟，全飞走了，树上还剩几只？", "englishAudio": null, "options": [], "answer": "0", "explanation": "全飞走了就是一只也不剩，一只也没有用 0 表示。", "verify": ""}, {"id": "hjm_g1a_u3_l2_q5", "topicId": "hjm_g1a_u3_l2", "difficulty": "hard", "type": "numeric", "prompt": "0、1、2、3 中最小的数是几？", "englishAudio": null, "options": [], "answer": "0", "explanation": "0 表示没有，比 1 还小，所以 0、1、2、3 中最小的是 0。容易错的是以为最小的是 1，忘了 0。", "verify": ""}, {"id": "hjm_g1a_u3_l3_q4", "topicId": "hjm_g1a_u3_l3", "difficulty": "medium", "type": "numeric", "prompt": "盒子里有 9 支笔，拿出 3 支，又拿出 2 支，还剩几支？", "englishAudio": null, "options": [], "answer": "4", "explanation": "拿出两次，要减两次：9-3-2=4，还剩 4 支。", "verify": "9-3-2"}, {"id": "hjm_g1a_u3_l3_q5", "topicId": "hjm_g1a_u3_l3", "difficulty": "hard", "type": "numeric", "prompt": "4 和 3 合起来是 7，那么 7 可以分成 4 和几？", "englishAudio": null, "options": [], "answer": "3", "explanation": "合起来和分开是反过来的：4 和 3 合起来是 7，所以 7 可以分成 4 和 3。", "verify": "7-4"}, {"id": "hjm_g1a_u3_l4_q4", "topicId": "hjm_g1a_u3_l4", "difficulty": "medium", "type": "numeric", "prompt": "6 前面第二个数是几？", "englishAudio": null, "options": [], "answer": "4", "explanation": "6 前面是 5，5 前面是 4，所以 6 前面第二个数是 4。", "verify": ""}, {"id": "hjm_g1a_u3_l4_q5", "topicId": "hjm_g1a_u3_l4", "difficulty": "hard", "type": "numeric", "prompt": "把 9、6、8 按从大到小排，排在中间的是几？", "englishAudio": null, "options": [], "answer": "8", "explanation": "从大到小排是 9、8、6，中间是 8。容易错的是按原来的顺序，中间就数成了 6。", "verify": ""}, {"id": "hjm_g1a_u3_l5_q4", "topicId": "hjm_g1a_u3_l5", "difficulty": "medium", "type": "numeric", "prompt": "一排有 10 个小朋友，从左数第 4 个是小红，从右数小红是第几个？", "englishAudio": null, "options": [], "answer": "7", "explanation": "一共 10 人，从左数第 4 个，从右数就是 10-4+1=7，第 7 个。", "verify": "10-4+1"}, {"id": "hjm_g1a_u3_l5_q5", "topicId": "hjm_g1a_u3_l5", "difficulty": "hard", "type": "numeric", "prompt": "10 里面有几个 2？", "englishAudio": null, "options": [], "answer": "5", "explanation": "2+2+2+2+2=10，一共 5 个 2。容易错的是以为 10 里面有 10 个 2。", "verify": ""}, {"id": "hjm_g1a_u3_l6_q4", "topicId": "hjm_g1a_u3_l6", "difficulty": "medium", "type": "numeric", "prompt": "妈妈买了 10 个鸡蛋，吃了 2 个，又吃了 3 个，还剩几个？", "englishAudio": null, "options": [], "answer": "5", "explanation": "吃了两次，要减两次：10-2-3=5，还剩 5 个。", "verify": "10-2-3"}, {"id": "hjm_g1a_u3_l6_q5", "topicId": "hjm_g1a_u3_l6", "difficulty": "hard", "type": "numeric", "prompt": "10 可以分成 6 和几？这个几再加 2 是几？（填最后的结果）", "englishAudio": null, "options": [], "answer": "6", "explanation": "先算 10-6=4，再算 4+2=6，最后的结果是 6。容易错的是做到第一步就停，答成 4。", "verify": "10-6+2"}, {"id": "hjm_g1a_u3_l7_q4", "topicId": "hjm_g1a_u3_l7", "difficulty": "medium", "type": "numeric", "prompt": "小华有 8 颗糖，吃了 2 颗，小丽有 5 颗糖，现在小华比小丽多几颗？", "englishAudio": null, "options": [], "answer": "1", "explanation": "先算小华还剩 8-2=6 颗，再算 6-5=1，现在小华比小丽多 1 颗。", "verify": "8-2-5"}, {"id": "hjm_g1a_u3_l7_q5", "topicId": "hjm_g1a_u3_l7", "difficulty": "hard", "type": "choice", "prompt": "9 比 6 大 3，反过来 6 比 9 小几？", "englishAudio": null, "options": ["3", "2", "4"], "answer": "3", "explanation": "大几和小几是一样的：9 比 6 大 3，6 就比 9 小 3。容易错的是以为反过来要换个数。", "verify": ""}, {"id": "hjm_g1a_u3_l8_q4", "topicId": "hjm_g1a_u3_l8", "difficulty": "medium", "type": "choice", "prompt": "5+2 ○ 8，○里填什么符号？", "englishAudio": null, "options": ["<", ">", "="], "answer": "<", "explanation": "先算 5+2=7，7 比 8 小，所以填小于号 <。", "verify": ""}, {"id": "hjm_g1a_u3_l8_q5", "topicId": "hjm_g1a_u3_l8", "difficulty": "hard", "type": "choice", "prompt": "下面哪个式子是错的？", "englishAudio": null, "options": ["4>3", "2<2", "6=6"], "answer": "2<2", "explanation": "4 比 3 大是对的，6 和 6 一样大是对的；2 和 2 一样大，应该填 =，不是 <，所以 2<2 是错的。", "verify": ""}, {"id": "hjm_g1a_u3_l9_q4", "topicId": "hjm_g1a_u3_l9", "difficulty": "medium", "type": "numeric", "prompt": "小明前面有 3 人，后面有 3 人，小明排第几？", "englishAudio": null, "options": [], "answer": "4", "explanation": "前面有 3 人，小明就是第 4 个。容易错的是把小明自己也算进前面的人里。", "verify": ""}, {"id": "hjm_g1a_u3_l9_q5", "topicId": "hjm_g1a_u3_l9", "difficulty": "hard", "type": "numeric", "prompt": "一排 10 只小动物，从左数小猫排第 3，从右数小猫排第几？", "englishAudio": null, "options": [], "answer": "8", "explanation": "一共 10 只，从左数第 3 只，从右数就是 10-3+1=8，第 8 只。容易错的是忘了加小猫自己，算成 7。", "verify": "10-3+1"}, {"id": "hjm_g1a_u4_l1_q4", "topicId": "hjm_g1a_u4_l1", "difficulty": "medium", "type": "numeric", "prompt": "树上有 5 只鸟，飞来 4 只，又飞走 2 只，现在有几只？", "englishAudio": null, "options": [], "answer": "7", "explanation": "飞来要加，飞走要减：5+4-2=7，现在有 7 只。", "verify": "5+4-2"}, {"id": "hjm_g1a_u4_l1_q5", "topicId": "hjm_g1a_u4_l1", "difficulty": "hard", "type": "numeric", "prompt": "□ + 3 = 8，□里填几？这个数再加 2 是几？（填最后的结果）", "englishAudio": null, "options": [], "answer": "7", "explanation": "先想 8 的分成：8 可以分成 5 和 3，所以□里填 5；再算 5+2=7，最后的结果是 7。容易错的是做到第一步就停，答成 5。", "verify": "8-3+2"}, {"id": "hjm_g1a_u4_l2_q4", "topicId": "hjm_g1a_u4_l2", "difficulty": "medium", "type": "numeric", "prompt": "讲一讲：公园里有 4 只鸭子，游走 1 只，又游来 5 只，现在有几只？", "englishAudio": null, "options": [], "answer": "8", "explanation": "游走要减，游来要加：4-1+5=8，现在有 8 只。", "verify": "4-1+5"}, {"id": "hjm_g1a_u4_l2_q5", "topicId": "hjm_g1a_u4_l2", "difficulty": "hard", "type": "numeric", "prompt": "讲一讲：篮子里有 8 个苹果，吃掉 3 个，又放进 4 个，再吃掉 2 个，现在有几个？", "englishAudio": null, "options": [], "answer": "7", "explanation": "按顺序算：8-3=5，5+4=9，9-2=7，现在有 7 个。容易错的是漏掉最后吃掉的 2 个。", "verify": "8-3+4-2"}, {"id": "hjm_g1a_u4_l3_q4", "topicId": "hjm_g1a_u4_l3", "difficulty": "medium", "type": "numeric", "prompt": "花瓶里有 9 朵花，枯了 4 朵，还剩几朵？再插进 3 朵，现在有几朵？（填最后的朵数）", "englishAudio": null, "options": [], "answer": "8", "explanation": "先算 9-4=5，再算 5+3=8，现在有 8 朵。", "verify": "9-4+3"}, {"id": "hjm_g1a_u4_l3_q5", "topicId": "hjm_g1a_u4_l3", "difficulty": "hard", "type": "numeric", "prompt": "□ - 5 = 3，□里填几？这个数再减去 2 是几？（填最后的结果）", "englishAudio": null, "options": [], "answer": "6", "explanation": "被减数 = 差 + 减数，3+5=8，所以□里填 8；再算 8-2=6，最后的结果是 6。容易错的是做到第一步就停，答成 8。", "verify": "3+5-2"}, {"id": "hjm_g1a_u4_l4_q4", "topicId": "hjm_g1a_u4_l4", "difficulty": "medium", "type": "numeric", "prompt": "讲一讲：小朋友有 10 颗珠子，送给妹妹 3 颗，又买来 2 颗，现在有几颗？", "englishAudio": null, "options": [], "answer": "9", "explanation": "送给别人要减，买来要加：10-3+2=9，现在有 9 颗。", "verify": "10-3+2"}, {"id": "hjm_g1a_u4_l4_q5", "topicId": "hjm_g1a_u4_l4", "difficulty": "hard", "type": "numeric", "prompt": "讲一讲：车上有 9 人，下车 5 人，上车 4 人，又下车 2 人，现在车上有几人？", "englishAudio": null, "options": [], "answer": "6", "explanation": "按顺序算：9-5=4，4+4=8，8-2=6，现在车上有 6 人。容易错的是漏掉最后下车的 2 人。", "verify": "9-5+4-2"}, {"id": "hjm_g1a_u4_l5_q4", "topicId": "hjm_g1a_u4_l5", "difficulty": "medium", "type": "numeric", "prompt": "小华上午写了 5 个字，下午写了 4 个字，擦掉 2 个错字，还剩几个字？", "englishAudio": null, "options": [], "answer": "7", "explanation": "写了要加，擦掉要减：5+4-2=7，还剩 7 个字。", "verify": "5+4-2"}, {"id": "hjm_g1a_u4_l5_q5", "topicId": "hjm_g1a_u4_l5", "difficulty": "hard", "type": "numeric", "prompt": "□ - 3 + 2 = 9，□里填几？", "englishAudio": null, "options": [], "answer": "10", "explanation": "倒着推：9-2=7，7+3=10，所以□里填 10。验算：10-3+2=9，对的。", "verify": "9-2+3"}, {"id": "hjm_g1a_u4_l6_q4", "topicId": "hjm_g1a_u4_l6", "difficulty": "medium", "type": "choice", "prompt": "10 的游戏：下面哪两个数加起来不是 10？", "englishAudio": null, "options": ["8和2", "5和5", "6和5"], "answer": "6和5", "explanation": "8+2=10，5+5=10，6+5=11，不是 10，所以选 6和5。", "verify": ""}, {"id": "hjm_g1a_u4_l6_q5", "topicId": "hjm_g1a_u4_l6", "difficulty": "hard", "type": "numeric", "prompt": "10 的游戏：□ + 3 = 10，□是几？□ 再减去 1 是几？（填最后的结果）", "englishAudio": null, "options": [], "answer": "6", "explanation": "先想 10 的分成：10 可以分成 7 和 3，所以□是 7；再算 7-1=6，最后的结果是 6。容易错的是做到第一步就停，答成 7。", "verify": "10-3-1"}, {"id": "hjm_g1a_u4_l7_q4", "topicId": "hjm_g1a_u4_l7", "difficulty": "medium", "type": "numeric", "prompt": "果盘里有 1 个苹果、5 个梨、3 个桃，一共有几个水果？", "englishAudio": null, "options": [], "answer": "9", "explanation": "按顺序加：1+5=6，6+3=9，一共有 9 个水果。", "verify": "1+5+3"}, {"id": "hjm_g1a_u4_l7_q5", "topicId": "hjm_g1a_u4_l7", "difficulty": "hard", "type": "numeric", "prompt": "小朋友有 10 颗糖，第一天吃 2 颗，第二天吃 3 颗，第三天吃 4 颗，还剩几颗？", "englishAudio": null, "options": [], "answer": "1", "explanation": "按顺序减：10-2=8，8-3=5，5-4=1，还剩 1 颗。容易错的是三天吃的合起来算错。", "verify": "10-2-3-4"}, {"id": "hjm_g1a_u4_l8_q4", "topicId": "hjm_g1a_u4_l8", "difficulty": "medium", "type": "numeric", "prompt": "花园里有 6 只蝴蝶，飞来 3 只，又飞走 4 只，现在有几只？", "englishAudio": null, "options": [], "answer": "5", "explanation": "飞来要加，飞走要减：6+3-4=5，现在有 5 只。", "verify": "6+3-4"}, {"id": "hjm_g1a_u4_l8_q5", "topicId": "hjm_g1a_u4_l8", "difficulty": "hard", "type": "choice", "prompt": "下面哪个算式的结果最小？", "englishAudio": null, "options": ["8-2+1", "4+4-2", "9-3-1"], "answer": "9-3-1", "explanation": "分别算出 8-2+1=7，4+4-2=6，9-3-1=5，最小的是 9-3-1。", "verify": ""}, {"id": "hjm_g1a_u5_l1_q4", "topicId": "hjm_g1a_u5_l1", "difficulty": "medium", "type": "numeric", "prompt": "2 个十是几？", "englishAudio": null, "options": [], "answer": "20", "explanation": "1 个十是 10，2 个十就是 10+10=20。", "verify": "10+10"}, {"id": "hjm_g1a_u5_l1_q5", "topicId": "hjm_g1a_u5_l1", "difficulty": "hard", "type": "numeric", "prompt": "一个数十位上是 1、个位上是 7，这个数比 10 大几？", "englishAudio": null, "options": [], "answer": "7", "explanation": "十位上是 1、个位上是 7 的数是 17，17-10=7，所以比 10 大 7。容易错的是直接答 17，忘了问的是大几。", "verify": "17-10"}, {"id": "hjm_g1a_u5_l2_q4", "topicId": "hjm_g1a_u5_l2", "difficulty": "medium", "type": "numeric", "prompt": "12 减去 10 是几？这个数再加上 5 是几？（填最后的结果）", "englishAudio": null, "options": [], "answer": "7", "explanation": "先算 12-10=2，再算 2+5=7，最后的结果是 7。", "verify": "12-10+5"}, {"id": "hjm_g1a_u5_l2_q5", "topicId": "hjm_g1a_u5_l2", "difficulty": "hard", "type": "numeric", "prompt": "一个数是十和 8，这个数减去 4 是几？", "englishAudio": null, "options": [], "answer": "14", "explanation": "十和 8 就是 18，18-4=14。容易错的是直接答 8，忘了先把十和 8 合成 18。", "verify": "18-4"}, {"id": "hjm_g1a_u5_l3_q4", "topicId": "hjm_g1a_u5_l3", "difficulty": "medium", "type": "numeric", "prompt": "把 11、18、15 按从小到大排，排在中间的是几？", "englishAudio": null, "options": [], "answer": "15", "explanation": "从小到大排是 11、15、18，中间是 15。", "verify": ""}, {"id": "hjm_g1a_u5_l3_q5", "topicId": "hjm_g1a_u5_l3", "difficulty": "hard", "type": "choice", "prompt": "下面哪一组是按从小到大排的？", "englishAudio": null, "options": ["13、15、17", "17、15、13", "15、13、17"], "answer": "13、15、17", "explanation": "从小到大是越来越大：13<15<17，只有第一组符合。容易错的是看错方向，把从大到小也当成对的。", "verify": ""}, {"id": "hjm_g1a_u6_l1_q4", "topicId": "hjm_g1a_u6_l1", "difficulty": "medium", "type": "numeric", "prompt": "小明有 12 张贴纸，又买了 6 张，一共有几张？", "englishAudio": null, "options": [], "answer": "18", "explanation": "12+6，把 2 和 6 先加得 8，再加 10，得 18。", "verify": "12+6"}, {"id": "hjm_g1a_u6_l1_q5", "topicId": "hjm_g1a_u6_l1", "difficulty": "hard", "type": "numeric", "prompt": "停车场有 19 辆车，开走 6 辆，又开来 3 辆，现在有几辆？", "englishAudio": null, "options": [], "answer": "16", "explanation": "开走要减，开来要加：19-6=13，13+3=16，现在有 16 辆。", "verify": "19-6+3"}, {"id": "hjm_g1a_u6_l2_q4", "topicId": "hjm_g1a_u6_l2", "difficulty": "medium", "type": "numeric", "prompt": "小红有 6 支铅笔，妈妈又买了 8 支，一共有几支？", "englishAudio": null, "options": [], "answer": "14", "explanation": "凑十法：6+4=10，10+4=14，所以一共 14 支。", "verify": "6+8"}, {"id": "hjm_g1a_u6_l2_q5", "topicId": "hjm_g1a_u6_l2", "difficulty": "hard", "type": "choice", "prompt": "下面哪个算式需要进位？", "englishAudio": null, "options": ["12+5", "8+7", "14+3"], "answer": "8+7", "explanation": "12+5=17，个位 2+5=7 不满十，不用进位；8+7=15，个位 8+7=15 满十，要进位；14+3=17，个位 4+3=7 不满十，不用进位。容易错的是看得数超过 10 就以为要进位。", "verify": ""}, {"id": "hjm_g1a_u6_l3_q4", "topicId": "hjm_g1a_u6_l3", "difficulty": "medium", "type": "numeric", "prompt": "加法表中，9 + 5 = 14，那么 14 - 9 = ？", "englishAudio": null, "options": [], "answer": "5", "explanation": "加法和减法是反过来的：9+5=14，所以 14-9=5。", "verify": "14-9"}, {"id": "hjm_g1a_u6_l3_q5", "topicId": "hjm_g1a_u6_l3", "difficulty": "hard", "type": "choice", "prompt": "加法表中，和是 15 的算式有很多，下面哪一个和不是 15？", "englishAudio": null, "options": ["7+8", "9+6", "8+8"], "answer": "8+8", "explanation": "7+8=15，9+6=15，8+8=16，不是 15。容易错的是以为 8+8 也是 15。", "verify": ""}, {"id": "hjm_g1b_u1_l1_q4", "topicId": "hjm_g1b_u1_l1", "difficulty": "medium", "type": "numeric", "prompt": "小林有18颗弹珠，先输掉7颗，又赢回5颗，现在有几颗弹珠？", "englishAudio": null, "options": [], "answer": "16", "explanation": "先算输掉后剩下18-7=11颗，再算赢回5颗：11+5=16颗。", "verify": "18-7+5"}, {"id": "hjm_g1b_u1_l1_q5", "topicId": "hjm_g1b_u1_l1", "difficulty": "hard", "type": "numeric", "prompt": "小树原来有一些气球，飞走6个后还剩9个，原来有几个气球？", "englishAudio": null, "options": [], "answer": "15", "explanation": "飞走6个后还剩9个，求原来用加法：6+9=15个。", "verify": "6+9"}, {"id": "hjm_g1b_u1_l2_q4", "topicId": "hjm_g1b_u1_l2", "difficulty": "medium", "type": "numeric", "prompt": "已知14-6=8，那么15-7的得数是几？", "englishAudio": null, "options": [], "answer": "8", "explanation": "14-6=8这一组里，被减数和减数同时增加1，得数不变：15-7和14-6是一组的，所以得数也是8。", "verify": "15-7"}, {"id": "hjm_g1b_u1_l2_q5", "topicId": "hjm_g1b_u1_l2", "difficulty": "hard", "type": "numeric", "prompt": "已知17-9=8，那么17-10的得数是几？", "englishAudio": null, "options": [], "answer": "7", "explanation": "被减数都是17，减数从9变成10，多减了1，得数就少1：8-1=7。", "verify": "17-10"}, {"id": "hjm_g1b_u1_l3_q4", "topicId": "hjm_g1b_u1_l3", "difficulty": "medium", "type": "numeric", "prompt": "小队有7名男生，女生比男生多5名，女生有几名？", "englishAudio": null, "options": [], "answer": "12", "explanation": "小队有7名男生，女生比男生多5名，求女生用加法：7+5=12名。", "verify": "7+5"}, {"id": "hjm_g1b_u1_l3_q5", "topicId": "hjm_g1b_u1_l3", "difficulty": "hard", "type": "numeric", "prompt": "车上有15位乘客，下去8位，又上来6位，现在有几位乘客？", "englishAudio": null, "options": [], "answer": "13", "explanation": "先算下去后剩下15-8=7位，再算上来后7+6=13位。", "verify": "15-8+6"}, {"id": "hjm_g1b_u1_l4_q4", "topicId": "hjm_g1b_u1_l4", "difficulty": "medium", "type": "choice", "prompt": "用5、7、12组一道减法算式，正确的是哪道？", "englishAudio": null, "options": ["12-5=7", "12+5=7", "5+12=7"], "answer": "12-5=7", "explanation": "用5、7、12组减法算式：总数是12，两个部分数是5和7，减法算式是12-5=7。", "verify": ""}, {"id": "hjm_g1b_u1_l4_q5", "topicId": "hjm_g1b_u1_l4", "difficulty": "hard", "type": "numeric", "prompt": "已知15-6=9，用6、9、15组成的加法算式的得数是几？", "englishAudio": null, "options": [], "answer": "15", "explanation": "6、9、15这一组数里，6和9是两个部分数，15是总数，加法算式是6+9=15，得数是15。", "verify": "6+9"}, {"id": "hjm_g1b_u2_l1_q4", "topicId": "hjm_g1b_u2_l1", "difficulty": "medium", "type": "numeric", "prompt": "从72往前数3个数是几？", "englishAudio": null, "options": [], "answer": "69", "explanation": "往前数就是倒着数：72往前数1个是71，数2个是70，数3个是69。", "verify": "72-3"}, {"id": "hjm_g1b_u2_l1_q5", "topicId": "hjm_g1b_u2_l1", "difficulty": "hard", "type": "numeric", "prompt": "从46开始，每次多10，数4次后是几？", "englishAudio": null, "options": [], "answer": "86", "explanation": "每次多10，数4次就是多4个10：46+10+10+10+10=86。", "verify": "46+10+10+10+10"}, {"id": "hjm_g1b_u2_l2_q4", "topicId": "hjm_g1b_u2_l2", "difficulty": "medium", "type": "choice", "prompt": "数字58读作什么？", "englishAudio": null, "options": ["五十八", "八十五", "五十"], "answer": "五十八", "explanation": "58的十位是5，个位是8，读作五十八；八十五是85，五十是50。", "verify": ""}, {"id": "hjm_g1b_u2_l2_q5", "topicId": "hjm_g1b_u2_l2", "difficulty": "hard", "type": "numeric", "prompt": "用数字卡片4、0组成一个两位数，这个两位数是几？", "englishAudio": null, "options": [], "answer": "40", "explanation": "用4和0组成两位数，十位不能是0，所以只能是40；04不是两位数。", "verify": ""}, {"id": "hjm_g1b_u2_l3_q4", "topicId": "hjm_g1b_u2_l3", "difficulty": "medium", "type": "numeric", "prompt": "74里面一共有几个一？", "englishAudio": null, "options": [], "answer": "74", "explanation": "74就是74个一合起来的数，所以74里面一共有74个一。", "verify": ""}, {"id": "hjm_g1b_u2_l3_q5", "topicId": "hjm_g1b_u2_l3", "difficulty": "hard", "type": "numeric", "prompt": "一个数，十位上的数比个位上的数大3，个位是4，这个数是几？", "englishAudio": null, "options": [], "answer": "74", "explanation": "个位是4，十位比个位大3，十位就是4+3=7，这个数是74。", "verify": ""}, {"id": "hjm_g1b_u2_l4_q4", "topicId": "hjm_g1b_u2_l4", "difficulty": "medium", "type": "choice", "prompt": "数轴上一个点在80和90之间，而且离80更近，这个点可能是几？", "englishAudio": null, "options": ["83", "88", "92"], "answer": "83", "explanation": "这个点在80和90之间，离80更近：83离80差3，88离80差8，92已经超过90，所以是83。", "verify": ""}, {"id": "hjm_g1b_u2_l4_q5", "topicId": "hjm_g1b_u2_l4", "difficulty": "hard", "type": "numeric", "prompt": "一个数在50和60之间，个位比十位小2，这个数是几？", "englishAudio": null, "options": [], "answer": "53", "explanation": "这个数在50和60之间，十位是5；个位比十位小2，个位就是5-2=3，这个数是53。", "verify": ""}, {"id": "hjm_g1b_u2_l5_q4", "topicId": "hjm_g1b_u2_l5", "difficulty": "medium", "type": "numeric", "prompt": "100里面有几个十？", "englishAudio": null, "options": [], "answer": "10", "explanation": "10个十是100，所以100里面有10个十。", "verify": ""}, {"id": "hjm_g1b_u2_l5_q5", "topicId": "hjm_g1b_u2_l5", "difficulty": "hard", "type": "numeric", "prompt": "100根小棒，每10根捆成一捆，捆了7捆后还剩几根？", "englishAudio": null, "options": [], "answer": "30", "explanation": "100根小棒，每10根一捆，捆了7捆就是70根，还剩100-70=30根。", "verify": "100-70"}, {"id": "hjm_g1b_u2_l6_q4", "topicId": "hjm_g1b_u2_l6", "difficulty": "medium", "type": "choice", "prompt": "63 ○ 36，圆圈里应该填什么符号？", "englishAudio": null, "options": [">", "<", "="], "answer": ">", "explanation": "比十位：63十位是6，36十位是3，6比3大，所以63比36大，填大于号。", "verify": ""}, {"id": "hjm_g1b_u2_l6_q5", "topicId": "hjm_g1b_u2_l6", "difficulty": "hard", "type": "numeric", "prompt": "用2、6、9组成一个最大的两位数和一个最小的两位数，它们的差是几？", "englishAudio": null, "options": [], "answer": "70", "explanation": "用2、6、9组成最大的两位数是96，最小的两位数是26，它们的差是96-26=70。", "verify": "96-26"}, {"id": "hjm_g1b_u2_l7_q4", "topicId": "hjm_g1b_u2_l7", "difficulty": "medium", "type": "numeric", "prompt": "与77相邻的两个数加起来是几？", "englishAudio": null, "options": [], "answer": "154", "explanation": "与77相邻的两个数是76和78，把它们加起来：76+78=154。", "verify": "76+78"}, {"id": "hjm_g1b_u2_l7_q5", "topicId": "hjm_g1b_u2_l7", "difficulty": "hard", "type": "numeric", "prompt": "83往后隔一个数是几？", "englishAudio": null, "options": [], "answer": "85", "explanation": "隔一个数就是往后数2个：83往后数1个是84，数2个是85。", "verify": ""}, {"id": "hjm_g1b_u3_l1_q4", "topicId": "hjm_g1b_u3_l1", "difficulty": "medium", "type": "numeric", "prompt": "分针指着12，时针快要指到5，还没到5，是几时？", "englishAudio": null, "options": [], "answer": "4", "explanation": "时针还没到5，说明还没到5时，现在是4时。", "verify": ""}, {"id": "hjm_g1b_u3_l1_q5", "topicId": "hjm_g1b_u3_l1", "difficulty": "hard", "type": "numeric", "prompt": "现在是5时，2小时前是几时？", "englishAudio": null, "options": [], "answer": "3", "explanation": "现在是5时，2小时前就是5-2=3时。", "verify": "5-2"}, {"id": "hjm_g1b_u3_l2_q4", "topicId": "hjm_g1b_u3_l2", "difficulty": "medium", "type": "choice", "prompt": "9时半，时针在几和几之间？", "englishAudio": null, "options": ["9和10之间", "8和9之间", "正好指着9"], "answer": "9和10之间", "explanation": "半时的时候，时针走过9、还没到10，在9和10之间。", "verify": ""}, {"id": "hjm_g1b_u3_l2_q5", "topicId": "hjm_g1b_u3_l2", "difficulty": "hard", "type": "choice", "prompt": "小亮画画结束时是7时半，画了半小时，开始是几时？", "englishAudio": null, "options": ["7时", "7时半", "8时"], "answer": "7时", "explanation": "结束是7时半，画了半小时，往回推半小时就是7时。", "verify": ""}, {"id": "hjm_g1b_u4_l1_q4", "topicId": "hjm_g1b_u4_l1", "difficulty": "medium", "type": "numeric", "prompt": "46+3=？", "englishAudio": null, "options": [], "answer": "49", "explanation": "46+3，十位不变是4，个位6+3=9，没有进位，是49。", "verify": "46+3"}, {"id": "hjm_g1b_u4_l1_q5", "topicId": "hjm_g1b_u4_l1", "difficulty": "hard", "type": "numeric", "prompt": "一个加数是24，和是68，另一个加数是几？", "englishAudio": null, "options": [], "answer": "44", "explanation": "一个加数是24，和是68，求另一个加数用减法：68-24=44。", "verify": "68-24"}, {"id": "hjm_g1b_u4_l2_q4", "topicId": "hjm_g1b_u4_l2", "difficulty": "medium", "type": "choice", "prompt": "28+36的得数比60大还是小？", "englishAudio": null, "options": ["比60大", "比60小", "等于60"], "answer": "比60大", "explanation": "28+36，个位8+6=14写4进1，十位2+3+1=6，是64，64比60大。", "verify": ""}, {"id": "hjm_g1b_u4_l2_q5", "topicId": "hjm_g1b_u4_l2", "difficulty": "hard", "type": "numeric", "prompt": "小明上午摘了28个苹果，下午摘了35个，晚上送出17个，还剩几个苹果？", "englishAudio": null, "options": [], "answer": "46", "explanation": "先算摘的一共28+35=63个，再算送出后63-17=46个。", "verify": "28+35-17"}, {"id": "hjm_g1b_u4_l3_q4", "topicId": "hjm_g1b_u4_l3", "difficulty": "medium", "type": "numeric", "prompt": "□+12+15=40，□是几？", "englishAudio": null, "options": [], "answer": "13", "explanation": "□+12+15=40，先算12+15=27，再算40-27=13，所以□是13。", "verify": "40-12-15"}, {"id": "hjm_g1b_u4_l3_q5", "topicId": "hjm_g1b_u4_l3", "difficulty": "hard", "type": "numeric", "prompt": "17+28+19=？", "englishAudio": null, "options": [], "answer": "64", "explanation": "连加从左往右算：17+28=45，45+19=64，中间有进位也要一步一步算。", "verify": "17+28+19"}, {"id": "hjm_g1b_u5_l1_q4", "topicId": "hjm_g1b_u5_l1", "difficulty": "medium", "type": "choice", "prompt": "小明的铅笔比小红的长，小红的比小亮的长，谁的铅笔最短？", "englishAudio": null, "options": ["小明", "小红", "小亮"], "answer": "小亮", "explanation": "小明的铅笔比小红的长，小红的比小亮的长，排下来是小明、小红、小亮，最短的是小亮。", "verify": ""}, {"id": "hjm_g1b_u5_l1_q5", "topicId": "hjm_g1b_u5_l1", "difficulty": "hard", "type": "choice", "prompt": "一根绳子对折后和另一根一样长，原来哪根长？", "englishAudio": null, "options": ["对折的那根", "没对折的那根", "两根一样长"], "answer": "对折的那根", "explanation": "对折后长度减半，还能和另一根一样长，说明对折的那根原来更长。", "verify": ""}, {"id": "hjm_g1b_u5_l2_q4", "topicId": "hjm_g1b_u5_l2", "difficulty": "medium", "type": "numeric", "prompt": "用直尺量物体，左端对准2厘米，右端对准9厘米，这个物体长几厘米？", "englishAudio": null, "options": [], "answer": "7", "explanation": "左端对准2厘米、右端对准9厘米，长度是两数之差：9-2=7厘米。", "verify": "9-2"}, {"id": "hjm_g1b_u5_l2_q5", "topicId": "hjm_g1b_u5_l2", "difficulty": "hard", "type": "numeric", "prompt": "一条彩带长30厘米，用去12厘米，又接上8厘米，现在长几厘米？", "englishAudio": null, "options": [], "answer": "26", "explanation": "先算用去后30-12=18厘米，再算接上后18+8=26厘米。", "verify": "30-12+8"}, {"id": "hjm_g1b_u5_l3_q4", "topicId": "hjm_g1b_u5_l3", "difficulty": "medium", "type": "numeric", "prompt": "两个点之间能画几条线段？", "englishAudio": null, "options": [], "answer": "1", "explanation": "两个点之间只能画一条直直的线段，所以是1条。", "verify": ""}, {"id": "hjm_g1b_u5_l3_q5", "topicId": "hjm_g1b_u5_l3", "difficulty": "hard", "type": "numeric", "prompt": "三个点（不在同一条直线上），每两个点连一条线段，一共能连几条线段？", "englishAudio": null, "options": [], "answer": "3", "explanation": "三个点两两连线：每两个点连一条，一共是3条。", "verify": ""}, {"id": "hjm_g1b_u6_l1_q4", "topicId": "hjm_g1b_u6_l1", "difficulty": "medium", "type": "numeric", "prompt": "小明一步约30厘米，他走了3步，大约走了几厘米？", "englishAudio": null, "options": [], "answer": "90", "explanation": "小明一步约30厘米，走3步就是3个30厘米：30+30+30=90厘米。", "verify": "30+30+30"}, {"id": "hjm_g1b_u6_l1_q5", "topicId": "hjm_g1b_u6_l1", "difficulty": "hard", "type": "choice", "prompt": "量同一张桌子，用拃量和用步量，哪种量的次数多？", "englishAudio": null, "options": ["用拃量的次数多", "用步量的次数多", "两次一样多"], "answer": "用拃量的次数多", "explanation": "拃比步短，量同样的长度，短的尺子要量更多次，所以用拃量的次数多。", "verify": ""}, {"id": "hjm_g1b_u6_l2_q4", "topicId": "hjm_g1b_u6_l2", "difficulty": "medium", "type": "numeric", "prompt": "书桌长约60厘米，小明一拃约15厘米，要量几拃？", "englishAudio": null, "options": [], "answer": "4", "explanation": "书桌长60厘米，一拃15厘米，15+15+15+15=60，所以要量4拃。", "verify": ""}, {"id": "hjm_g1b_u6_l2_q5", "topicId": "hjm_g1b_u6_l2", "difficulty": "hard", "type": "choice", "prompt": "同样量5拃，小明一拃9厘米，小红一拃11厘米，谁量出的长度长？", "englishAudio": null, "options": ["小明", "小红", "一样长"], "answer": "小红", "explanation": "同样量5拃，单次长的总量就长：小红一拃11厘米比小明一拃9厘米长，所以小红量出的长度长。", "verify": ""}, {"id": "hjm_g1b_u6_l3_q4", "topicId": "hjm_g1b_u6_l3", "difficulty": "medium", "type": "numeric", "prompt": "从1米处开始每2米挂一面彩旗，到9米处一共挂了几面？", "englishAudio": null, "options": [], "answer": "5", "explanation": "从1米处开始每2米一面：1米、3米、5米、7米、9米，数一数共5面。", "verify": ""}, {"id": "hjm_g1b_u6_l3_q5", "topicId": "hjm_g1b_u6_l3", "difficulty": "hard", "type": "numeric", "prompt": "一排彩旗共7面，相邻两面相隔2米，从第1面到第7面一共长几米？", "englishAudio": null, "options": [], "answer": "12", "explanation": "7面彩旗有6个间隔，每个间隔2米，6个间隔就是（7-1）×2=12米。", "verify": "(7-1)*2"}, {"id": "hjm_g1b_u7_l1_q4", "topicId": "hjm_g1b_u7_l1", "difficulty": "medium", "type": "numeric", "prompt": "30、27、24，后面一个数是几？", "englishAudio": null, "options": [], "answer": "21", "explanation": "30、27、24每次少3，下一个就是24-3=21。", "verify": "24-3"}, {"id": "hjm_g1b_u7_l1_q5", "topicId": "hjm_g1b_u7_l1", "difficulty": "hard", "type": "numeric", "prompt": "1、3、2、4、3、5，后面一个数是几？", "englishAudio": null, "options": [], "answer": "4", "explanation": "隔着看：1、2、3和3、4、5各成一排，下一个回到第一排，是4。", "verify": ""}, {"id": "hjm_g1b_u7_l2_q4", "topicId": "hjm_g1b_u7_l2", "difficulty": "medium", "type": "numeric", "prompt": "数墙底层是2、6、4，中间层左块是几？", "englishAudio": null, "options": [], "answer": "8", "explanation": "中间层左块等于底层前两块的和：2+6=8。", "verify": "2+6"}, {"id": "hjm_g1b_u7_l2_q5", "topicId": "hjm_g1b_u7_l2", "difficulty": "hard", "type": "numeric", "prompt": "数墙底层是4、□、9，中间层是11、16，□是几？", "englishAudio": null, "options": [], "answer": "7", "explanation": "中间层左块11等于底层4和□的和，求□用减法：11-4=7。", "verify": "11-4"}, {"id": "hjm_g1a_u1_l1_q6", "topicId": "hjm_g1a_u1_l1", "difficulty": "medium", "type": "numeric", "prompt": "说一说：小树上有 7 只小鸟，飞走 3 只，又飞来 2 只，现在有几只小鸟？", "englishAudio": null, "options": [], "answer": "6", "explanation": "7 只飞走 3 只剩 4 只，又飞来 2 只就是 6 只。", "verify": "7-3+2"}, {"id": "hjm_g1a_u1_l1_q7", "topicId": "hjm_g1a_u1_l1", "difficulty": "hard", "type": "numeric", "prompt": "说一说：小明有 5 元，买气球花了 2 元，妈妈又给他 4 元，他现在有几元？再买 3 元的冰淇淋，还剩几元？（填最后的钱数）", "englishAudio": null, "options": [], "answer": "4", "explanation": "5-2=3，3+4=7，7-3=4，最后还剩 4 元。", "verify": "5-2+4-3"}, {"id": "hjm_g1a_u1_l2_q6", "topicId": "hjm_g1a_u1_l2", "difficulty": "medium", "type": "numeric", "prompt": "玩一玩：踢毽子，小红第一次踢了 3 下，第二次踢了 4 下，第三次踢了 2 下，一共踢了几下？", "englishAudio": null, "options": [], "answer": "9", "explanation": "3+4=7，7+2=9，一共踢了 9 下。", "verify": "3+4+2"}, {"id": "hjm_g1a_u1_l2_q7", "topicId": "hjm_g1a_u1_l2", "difficulty": "hard", "type": "numeric", "prompt": "玩一玩：丢手绢游戏，原来有 10 个小朋友，走了 3 个，又来了 5 个，再走 2 个，现在有几个小朋友？", "englishAudio": null, "options": [], "answer": "10", "explanation": "10-3=7，7+5=12，12-2=10，现在有 10 个小朋友。", "verify": "10-3+5-2"}, {"id": "hjm_g1a_u1_l3_q6", "topicId": "hjm_g1a_u1_l3", "difficulty": "medium", "type": "numeric", "prompt": "认一认：把 8、3、6、1 按从大到小排，排在第 2 个的是几？", "englishAudio": null, "options": [], "answer": "6", "explanation": "从大到小是 8、6、3、1，第 2 个是 6。", "verify": ""}, {"id": "hjm_g1a_u1_l3_q7", "topicId": "hjm_g1a_u1_l3", "difficulty": "hard", "type": "numeric", "prompt": "认一认：小丽从 5 开始往前数（倒着数），数到第 4 个数是几？", "englishAudio": null, "options": [], "answer": "2", "explanation": "倒着数是 5、4、3、2，第 4 个是 2。", "verify": ""}, {"id": "hjm_g1a_u2_l1_q6", "topicId": "hjm_g1a_u2_l1", "difficulty": "medium", "type": "choice", "prompt": "认识立体图形：搭积木时，下面哪个立体图形最容易滚动？", "englishAudio": null, "options": ["正方体", "球", "长方体"], "answer": "球", "explanation": "球是圆圆的，没有平平的面，一推就滚动；正方体和长方体有平平的面，立得稳。", "verify": ""}, {"id": "hjm_g1a_u2_l1_q7", "topicId": "hjm_g1a_u2_l1", "difficulty": "hard", "type": "numeric", "prompt": "认识立体图形：一个长方体有 6 个面，两个长方体拼在一起（拼掉 2 个面），现在外面一共能看到几个面？", "englishAudio": null, "options": [], "answer": "10", "explanation": "两个长方体一共 12 个面，拼在一起藏起了 2 个面，外面能看到 12-2=10 个面。", "verify": "6+6-2"}, {"id": "hjm_g1a_u2_l2_q6", "topicId": "hjm_g1a_u2_l2", "difficulty": "medium", "type": "choice", "prompt": "认识平面图形：用 4 根一样长的小棒可以围成什么图形？", "englishAudio": null, "options": ["长方形", "正方形", "三角形"], "answer": "正方形", "explanation": "4 根一样长的小棒围成的四边形，四条边一样长，就是正方形；三角形只要 3 根小棒。", "verify": ""}, {"id": "hjm_g1a_u2_l2_q7", "topicId": "hjm_g1a_u2_l2", "difficulty": "hard", "type": "choice", "prompt": "认识平面图形：一个正方形剪去一个角，还剩几个角？", "englishAudio": null, "options": ["3", "4", "5"], "answer": "5", "explanation": "剪去一个角的地方会多出两个角，原来 4 个角减 1 个加 2 个，还剩 5 个角。", "verify": ""}, {"id": "hjm_g1a_u3_l1_q6", "topicId": "hjm_g1a_u3_l1", "difficulty": "medium", "type": "choice", "prompt": "下面哪个数在 2 和 5 之间？", "englishAudio": null, "options": ["1", "3", "6"], "answer": "3", "explanation": "比 2 大、比 5 小的数是 3 和 4，选项里只有 3。", "verify": ""}, {"id": "hjm_g1a_u3_l1_q7", "topicId": "hjm_g1a_u3_l1", "difficulty": "hard", "type": "numeric", "prompt": "把 4、1、5、2、3 按从大到小排，排在第 2 个的是几？", "englishAudio": null, "options": [], "answer": "4", "explanation": "从大到小是 5、4、3、2、1，第 2 个是 4。", "verify": ""}, {"id": "hjm_g1a_u3_l2_q6", "topicId": "hjm_g1a_u3_l2", "difficulty": "medium", "type": "numeric", "prompt": "5 - 5 + 2 = ？", "englishAudio": null, "options": [], "answer": "2", "explanation": "5-5=0，0+2=2。", "verify": "5-5+2"}, {"id": "hjm_g1a_u3_l2_q7", "topicId": "hjm_g1a_u3_l2", "difficulty": "hard", "type": "choice", "prompt": "下面哪个算式的结果不是 0？", "englishAudio": null, "options": ["4-4", "0+0", "5-0"], "answer": "5-0", "explanation": "4-4=0，0+0=0，5-0=5，只有 5-0 的结果不是 0。", "verify": ""}, {"id": "hjm_g1a_u3_l3_q6", "topicId": "hjm_g1a_u3_l3", "difficulty": "medium", "type": "choice", "prompt": "下面哪组数合起来是 8？", "englishAudio": null, "options": ["3和4", "5和3", "2和5"], "answer": "5和3", "explanation": "3+4=7，5+3=8，2+5=7，只有 5 和 3 合起来是 8。", "verify": ""}, {"id": "hjm_g1a_u3_l3_q7", "topicId": "hjm_g1a_u3_l3", "difficulty": "hard", "type": "numeric", "prompt": "小明原来有 10 颗糖，吃了 3 颗，又买来 2 颗，现在有几颗？再送给弟弟 4 颗，还剩几颗？（填最后的颗数）", "englishAudio": null, "options": [], "answer": "5", "explanation": "10-3=7，7+2=9，9-4=5，最后还剩 5 颗。", "verify": "10-3+2-4"}, {"id": "hjm_g1a_u3_l4_q6", "topicId": "hjm_g1a_u3_l4", "difficulty": "medium", "type": "choice", "prompt": "下面哪个数比 7 大、比 10 小？", "englishAudio": null, "options": ["6", "8", "10"], "answer": "8", "explanation": "比 7 大、比 10 小的数是 8 和 9，选项里只有 8。", "verify": ""}, {"id": "hjm_g1a_u3_l4_q7", "topicId": "hjm_g1a_u3_l4", "difficulty": "hard", "type": "numeric", "prompt": "把 6、9、7、8 按从小到大排，排在第 3 个的是几？", "englishAudio": null, "options": [], "answer": "8", "explanation": "从小到大是 6、7、8、9，第 3 个是 8。", "verify": ""}, {"id": "hjm_g1a_u3_l5_q6", "topicId": "hjm_g1a_u3_l5", "difficulty": "medium", "type": "numeric", "prompt": "盘子里有 10 个包子，吃了 3 个，又蒸了 2 个，现在有几个？", "englishAudio": null, "options": [], "answer": "9", "explanation": "10-3=7，7+2=9，现在有 9 个。", "verify": "10-3+2"}, {"id": "hjm_g1a_u3_l5_q7", "topicId": "hjm_g1a_u3_l5", "difficulty": "hard", "type": "choice", "prompt": "□ + □ = 10，两个□里的数不一样，可以是哪两个？", "englishAudio": null, "options": ["5和5", "4和6", "3和3"], "answer": "4和6", "explanation": "5+5=10 但两个数一样，3+3=6 不是 10，只有 4+6=10 且两个数不一样。", "verify": ""}, {"id": "hjm_g1a_u3_l6_q6", "topicId": "hjm_g1a_u3_l6", "difficulty": "medium", "type": "choice", "prompt": "下面哪两个数合起来是 10？", "englishAudio": null, "options": ["3和6", "8和2", "5和4"], "answer": "8和2", "explanation": "3+6=9，8+2=10，5+4=9，只有 8 和 2 合起来是 10。", "verify": ""}, {"id": "hjm_g1a_u3_l6_q7", "topicId": "hjm_g1a_u3_l6", "difficulty": "hard", "type": "numeric", "prompt": "小明原来有 10 颗糖，吃了一些后还剩 4 颗，再吃 1 颗，还剩几颗？", "englishAudio": null, "options": [], "answer": "3", "explanation": "吃了一些后还剩 4 颗，再吃 1 颗，4-1=3，还剩 3 颗。", "verify": "4-1"}, {"id": "hjm_g1a_u3_l7_q6", "topicId": "hjm_g1a_u3_l7", "difficulty": "medium", "type": "numeric", "prompt": "小强有 9 颗糖，小刚有 4 颗糖，小强比小刚多几颗？", "englishAudio": null, "options": [], "answer": "5", "explanation": "9-4=5，小强比小刚多 5 颗。", "verify": "9-4"}, {"id": "hjm_g1a_u3_l7_q7", "topicId": "hjm_g1a_u3_l7", "difficulty": "hard", "type": "numeric", "prompt": "有两堆苹果，第一堆 6 个，第二堆比第一堆少 2 个，两堆一共有几个？", "englishAudio": null, "options": [], "answer": "10", "explanation": "第二堆是 6-2=4 个，两堆一共 6+4=10 个。", "verify": "6+6-2"}, {"id": "hjm_g1a_u3_l8_q6", "topicId": "hjm_g1a_u3_l8", "difficulty": "medium", "type": "choice", "prompt": "“9 比 5 大，5 比 9 小”这句话对吗？（填对或错）", "englishAudio": null, "options": ["对", "错"], "answer": "对", "explanation": "9 比 5 大是对的，反过来说 5 比 9 小也是对的。", "verify": ""}, {"id": "hjm_g1a_u3_l8_q7", "topicId": "hjm_g1a_u3_l8", "difficulty": "hard", "type": "choice", "prompt": "□ > 6，□里可以填几？", "englishAudio": null, "options": ["5", "6", "9"], "answer": "9", "explanation": "□ 要比 6 大，5 比 6 小，6 和 6 一样大，只有 9 比 6 大。", "verify": ""}, {"id": "hjm_g1a_u3_l9_q6", "topicId": "hjm_g1a_u3_l9", "difficulty": "medium", "type": "numeric", "prompt": "小明排第 2，小红排第 5，小明和小红之间有几人？", "englishAudio": null, "options": [], "answer": "2", "explanation": "从第 2 到第 5，中间隔着第 3、第 4，5-2-1=2，有 2 人。", "verify": "5-2-1"}, {"id": "hjm_g1a_u3_l9_q7", "topicId": "hjm_g1a_u3_l9", "difficulty": "hard", "type": "numeric", "prompt": "一排 10 个小朋友，从左数小刚排第 3，从右数小红排第 2，他们之间有几人？", "englishAudio": null, "options": [], "answer": "5", "explanation": "小红从左数是 10-2+1=9，第 3 和第 9 之间有 9-3-1=5 人。", "verify": "10-2+1-3-1"}, {"id": "hjm_g1a_u4_l1_q6", "topicId": "hjm_g1a_u4_l1", "difficulty": "medium", "type": "numeric", "prompt": "小明上午做了 3 道题，下午做了 4 道题，晚上又做了 2 道题，一共做了几道题？", "englishAudio": null, "options": [], "answer": "9", "explanation": "3+4=7，7+2=9，一共做了 9 道题。", "verify": "3+4+2"}, {"id": "hjm_g1a_u4_l1_q7", "topicId": "hjm_g1a_u4_l1", "difficulty": "hard", "type": "numeric", "prompt": "小红有 3 颗糖，小明比小红多 2 颗，两人一共几颗？", "englishAudio": null, "options": [], "answer": "8", "explanation": "小明有 3+2=5 颗，两人一共 3+5=8 颗。", "verify": "3+3+2"}, {"id": "hjm_g1a_u4_l2_q6", "topicId": "hjm_g1a_u4_l2", "difficulty": "medium", "type": "numeric", "prompt": "讲一讲：小朋友们玩球，原来有 5 个球，买来 3 个，破了 1 个，又买来 2 个，现在有几个球？", "englishAudio": null, "options": [], "answer": "9", "explanation": "5+3=8，8-1=7，7+2=9，现在有 9 个球。", "verify": "5+3-1+2"}, {"id": "hjm_g1a_u4_l2_q7", "topicId": "hjm_g1a_u4_l2", "difficulty": "hard", "type": "numeric", "prompt": "讲一讲：妈妈买了 10 个鸡蛋，吃了 3 个，妈妈又买来 5 个，爸爸吃了 2 个，现在有几个鸡蛋？", "englishAudio": null, "options": [], "answer": "10", "explanation": "10-3=7，7+5=12，12-2=10，现在有 10 个鸡蛋。", "verify": "10-3+5-2"}, {"id": "hjm_g1a_u4_l3_q6", "topicId": "hjm_g1a_u4_l3", "difficulty": "medium", "type": "numeric", "prompt": "小朋友有 9 元，买橡皮花了 4 元，还剩几元？再买 2 元的铅笔，还剩几元？（填最后的钱数）", "englishAudio": null, "options": [], "answer": "3", "explanation": "9-4=5，5-2=3，最后还剩 3 元。", "verify": "9-4-2"}, {"id": "hjm_g1a_u4_l3_q7", "topicId": "hjm_g1a_u4_l3", "difficulty": "hard", "type": "numeric", "prompt": "小明有一些糖，吃了 5 颗后还剩 6 颗，他原来有几颗？再吃 2 颗，还剩几颗？（填最后的颗数）", "englishAudio": null, "options": [], "answer": "9", "explanation": "原来有 5+6=11 颗，再吃 2 颗，11-2=9，还剩 9 颗。", "verify": "5+6-2"}, {"id": "hjm_g1a_u4_l4_q6", "topicId": "hjm_g1a_u4_l4", "difficulty": "medium", "type": "numeric", "prompt": "讲一讲：果园里有 7 只小鸟，飞走 2 只，又飞来 4 只，再飞走 1 只，现在有几只？", "englishAudio": null, "options": [], "answer": "8", "explanation": "7-2=5，5+4=9，9-1=8，现在有 8 只。", "verify": "7-2+4-1"}, {"id": "hjm_g1a_u4_l4_q7", "topicId": "hjm_g1a_u4_l4", "difficulty": "hard", "type": "numeric", "prompt": "讲一讲：小华有 10 元，买书花了 3 元，买本子花了 2 元，妈妈又给他 5 元，现在有几元？", "englishAudio": null, "options": [], "answer": "10", "explanation": "10-3=7，7-2=5，5+5=10，现在有 10 元。", "verify": "10-3-2+5"}, {"id": "hjm_g1a_u4_l5_q6", "topicId": "hjm_g1a_u4_l5", "difficulty": "medium", "type": "numeric", "prompt": "小明有 7 颗糖，给弟弟 2 颗，又买来 4 颗，现在有几颗？", "englishAudio": null, "options": [], "answer": "9", "explanation": "7-2=5，5+4=9，现在有 9 颗。", "verify": "7-2+4"}, {"id": "hjm_g1a_u4_l5_q7", "topicId": "hjm_g1a_u4_l5", "difficulty": "hard", "type": "numeric", "prompt": "小红原来有 6 元，妈妈给她一些钱后，她花了 4 元，还剩 5 元，妈妈给了她几元？", "englishAudio": null, "options": [], "answer": "3", "explanation": "花了 4 元还剩 5 元，说明给钱后一共是 4+5=9 元，妈妈给了 9-6=3 元。", "verify": ""}, {"id": "hjm_g1a_u4_l6_q6", "topicId": "hjm_g1a_u4_l6", "difficulty": "medium", "type": "numeric", "prompt": "10 的游戏：3 + □ + 4 = 10，□里填几？", "englishAudio": null, "options": [], "answer": "3", "explanation": "3+4=7，10-7=3，□里填 3。", "verify": "10-3-4"}, {"id": "hjm_g1a_u4_l6_q7", "topicId": "hjm_g1a_u4_l6", "difficulty": "hard", "type": "numeric", "prompt": "10 的游戏：小明带了 10 元，买橡皮花 3 元，买铅笔花 4 元，还剩几元？", "englishAudio": null, "options": [], "answer": "3", "explanation": "10-3=7，7-4=3，还剩 3 元。", "verify": "10-3-4"}, {"id": "hjm_g1a_u4_l7_q6", "topicId": "hjm_g1a_u4_l7", "difficulty": "medium", "type": "numeric", "prompt": "停车场有 8 辆车，开走 2 辆，又开走 3 辆，还剩几辆？", "englishAudio": null, "options": [], "answer": "3", "explanation": "8-2=6，6-3=3，还剩 3 辆。", "verify": "8-2-3"}, {"id": "hjm_g1a_u4_l7_q7", "topicId": "hjm_g1a_u4_l7", "difficulty": "hard", "type": "numeric", "prompt": "小明有 10 元，买书花了 4 元，买笔花了 3 元，又买橡皮花了 2 元，还剩几元？", "englishAudio": null, "options": [], "answer": "1", "explanation": "10-4=6，6-3=3，3-2=1，还剩 1 元。", "verify": "10-4-3-2"}, {"id": "hjm_g1a_u4_l8_q6", "topicId": "hjm_g1a_u4_l8", "difficulty": "medium", "type": "choice", "prompt": "下面哪个算式的结果是 9？", "englishAudio": null, "options": ["6+2-1", "8-2+3", "4+4-2"], "answer": "8-2+3", "explanation": "6+2-1=7，8-2+3=9，4+4-2=6，只有 8-2+3 的结果是 9。", "verify": ""}, {"id": "hjm_g1a_u4_l8_q7", "topicId": "hjm_g1a_u4_l8", "difficulty": "hard", "type": "numeric", "prompt": "小朋友跳绳，第一组跳了 7 下，第二组比第一组多跳 2 下，第三组比第二组少跳 3 下，第三组跳了几下？", "englishAudio": null, "options": [], "answer": "6", "explanation": "第二组跳 7+2=9 下，第三组跳 9-3=6 下。", "verify": "7+2-3"}, {"id": "hjm_g1a_u5_l1_q6", "topicId": "hjm_g1a_u5_l1", "difficulty": "medium", "type": "numeric", "prompt": "一个数是 2 个十，它比 15 大几？", "englishAudio": null, "options": [], "answer": "5", "explanation": "2 个十是 20，20-15=5，大 5。", "verify": "20-15"}, {"id": "hjm_g1a_u5_l1_q7", "topicId": "hjm_g1a_u5_l1", "difficulty": "hard", "type": "numeric", "prompt": "一个数十位上是 1、个位上是 9，这个数减去 10 是几？再减去 3 是几？（填最后的结果）", "englishAudio": null, "options": [], "answer": "6", "explanation": "这个数是 19，19-10=9，9-3=6，最后是 6。", "verify": "19-10-3"}, {"id": "hjm_g1a_u5_l2_q6", "topicId": "hjm_g1a_u5_l2", "difficulty": "medium", "type": "numeric", "prompt": "17 比 14 大几？", "englishAudio": null, "options": [], "answer": "3", "explanation": "17-14=3，大 3。", "verify": "17-14"}, {"id": "hjm_g1a_u5_l2_q7", "topicId": "hjm_g1a_u5_l2", "difficulty": "hard", "type": "numeric", "prompt": "一个数是十和 5，这个数比 12 大几？再减去 2 是几？（填最后的结果）", "englishAudio": null, "options": [], "answer": "1", "explanation": "这个数是 15，15-12=3，3-2=1，最后是 1。", "verify": "15-12-2"}, {"id": "hjm_g1a_u5_l3_q6", "topicId": "hjm_g1a_u5_l3", "difficulty": "medium", "type": "numeric", "prompt": "13、□、17、19，□里填几？", "englishAudio": null, "options": [], "answer": "15", "explanation": "每次加 2：13、15、17、19，□里填 15。", "verify": ""}, {"id": "hjm_g1a_u5_l3_q7", "topicId": "hjm_g1a_u5_l3", "difficulty": "hard", "type": "numeric", "prompt": "把 12、20、16、18 按从大到小排，排在第 2 个的是几？", "englishAudio": null, "options": [], "answer": "18", "explanation": "从大到小是 20、18、16、12，第 2 个是 18。", "verify": ""}, {"id": "hjm_g1a_u6_l1_q6", "topicId": "hjm_g1a_u6_l1", "difficulty": "medium", "type": "numeric", "prompt": "小朋友有 16 元，买书花了 4 元，还剩几元？再买 2 元的橡皮，还剩几元？（填最后的钱数）", "englishAudio": null, "options": [], "answer": "10", "explanation": "16-4=12，12-2=10，最后还剩 10 元。", "verify": "16-4-2"}, {"id": "hjm_g1a_u6_l1_q7", "topicId": "hjm_g1a_u6_l1", "difficulty": "hard", "type": "numeric", "prompt": "□ + 5 = 19，□是几？□ 再减去 3 是几？（填最后的结果）", "englishAudio": null, "options": [], "answer": "11", "explanation": "□ 是 19-5=14，14-3=11，最后是 11。", "verify": "19-5-3"}, {"id": "hjm_g1a_u6_l2_q6", "topicId": "hjm_g1a_u6_l2", "difficulty": "medium", "type": "choice", "prompt": "下面哪个算式的结果是 14？", "englishAudio": null, "options": ["9+4", "8+6", "7+5"], "answer": "8+6", "explanation": "9+4=13，8+6=14，7+5=12，只有 8+6 的结果是 14。", "verify": ""}, {"id": "hjm_g1a_u6_l2_q7", "topicId": "hjm_g1a_u6_l2", "difficulty": "hard", "type": "numeric", "prompt": "小明有 8 颗糖，妈妈又给他 7 颗，他一共有几颗？再分给弟弟 4 颗，还剩几颗？（填最后的颗数）", "englishAudio": null, "options": [], "answer": "11", "explanation": "8+7=15，15-4=11，还剩 11 颗。", "verify": "8+7-4"}, {"id": "hjm_g1a_u6_l3_q6", "topicId": "hjm_g1a_u6_l3", "difficulty": "medium", "type": "numeric", "prompt": "加法表中，9 + 6 = 15，那么 9 + 7 比 15 大几？", "englishAudio": null, "options": [], "answer": "1", "explanation": "9+7=16，16-15=1，大 1。", "verify": "9+7-15"}, {"id": "hjm_g1a_u6_l3_q7", "topicId": "hjm_g1a_u6_l3", "difficulty": "hard", "type": "numeric", "prompt": "加法表中，5 + 6 = 11，6 + 6 = 12，7 + 6 = ？", "englishAudio": null, "options": [], "answer": "13", "explanation": "第一个加数每次加 1，和也加 1，7+6=13。", "verify": "7+6"}, {"id": "hjm_g1b_u1_l1_q6", "topicId": "hjm_g1b_u1_l1", "difficulty": "medium", "type": "numeric", "prompt": "小华有16颗葡萄，吃了9颗，又买了7颗，现在有几颗葡萄？", "englishAudio": null, "options": [], "answer": "14", "explanation": "先算16-9=7，再算7+7=14，现在有14颗葡萄。", "verify": "16-9+7"}, {"id": "hjm_g1b_u1_l1_q7", "topicId": "hjm_g1b_u1_l1", "difficulty": "hard", "type": "numeric", "prompt": "小红有15支笔，小明比小红少6支，两人一共几支笔？", "englishAudio": null, "options": [], "answer": "24", "explanation": "先算小明有15-6=9支，再算两人一共9+15=24支。", "verify": "15-6+15"}, {"id": "hjm_g1b_u1_l2_q6", "topicId": "hjm_g1b_u1_l2", "difficulty": "medium", "type": "numeric", "prompt": "11-4=7，12-4=8，13-4=？", "englishAudio": null, "options": [], "answer": "9", "explanation": "被减数每次多1，减数不变，得数也每次多1：7、8后面是9。", "verify": "13-4"}, {"id": "hjm_g1b_u1_l2_q7", "topicId": "hjm_g1b_u1_l2", "difficulty": "hard", "type": "choice", "prompt": "14-6=8，15-7=8，16-8=8，下面哪道算式的得数也是8？", "englishAudio": null, "options": ["17-9", "17-8", "18-9"], "answer": "17-9", "explanation": "被减数和减数同时加1，得数不变：14-6=8，15-7=8，16-8=8，所以17-9=8；17-8=9，18-9=9。", "verify": ""}, {"id": "hjm_g1b_u1_l3_q6", "topicId": "hjm_g1b_u1_l3", "difficulty": "medium", "type": "numeric", "prompt": "桃树上有16个桃子，摘了8个，又长出5个，现在有几个桃子？", "englishAudio": null, "options": [], "answer": "13", "explanation": "先算16-8=8，再算8+5=13，现在有13个桃子。", "verify": "16-8+5"}, {"id": "hjm_g1b_u1_l3_q7", "topicId": "hjm_g1b_u1_l3", "difficulty": "hard", "type": "numeric", "prompt": "小军有11辆小汽车，小强比小军多4辆，小丽比小强少3辆，小丽有几辆小汽车？", "englishAudio": null, "options": [], "answer": "12", "explanation": "先算小强有11+4=15辆，再算小丽有15-3=12辆。", "verify": "11+4-3"}, {"id": "hjm_g1b_u1_l4_q6", "topicId": "hjm_g1b_u1_l4", "difficulty": "medium", "type": "choice", "prompt": "用6、9、15组一道加法算式，正确的是哪道？", "englishAudio": null, "options": ["6+9=15", "9+15=6", "6+15=9"], "answer": "6+9=15", "explanation": "两个小数相加等于大数：6+9=15；9+15=24不是6，6+15=21不是9。", "verify": ""}, {"id": "hjm_g1b_u1_l4_q7", "topicId": "hjm_g1b_u1_l4", "difficulty": "hard", "type": "choice", "prompt": "下面哪道算式不能用6、10、16组成？", "englishAudio": null, "options": ["6+10=16", "16-6=10", "10-6=16"], "answer": "10-6=16", "explanation": "6+10=16和16-6=10都对；10-6=4不是16，所以10-6=16不能组成。", "verify": ""}, {"id": "hjm_g1b_u2_l1_q6", "topicId": "hjm_g1b_u2_l1", "difficulty": "medium", "type": "numeric", "prompt": "从95开始，每次少5，数3次后是几？", "englishAudio": null, "options": [], "answer": "80", "explanation": "95减5是90，再减5是85，再减5是80。", "verify": "95-5-5-5"}, {"id": "hjm_g1b_u2_l1_q7", "topicId": "hjm_g1b_u2_l1", "difficulty": "hard", "type": "numeric", "prompt": "小朋友们排队报数，从左往右数小红是第18个，从右往左数她是第5个，这队一共几人？", "englishAudio": null, "options": [], "answer": "22", "explanation": "两边都数了小红一次，要减去重复的1次：18+5-1=22人。", "verify": "18+5-1"}, {"id": "hjm_g1b_u2_l2_q6", "topicId": "hjm_g1b_u2_l2", "difficulty": "medium", "type": "choice", "prompt": "一个数，个位是6，十位是3，这个数读作什么？", "englishAudio": null, "options": ["三十六", "六十三", "三十"], "answer": "三十六", "explanation": "十位是3读三十，个位是6读六，合起来读三十六；六十三是把十位个位弄反了。", "verify": ""}, {"id": "hjm_g1b_u2_l2_q7", "topicId": "hjm_g1b_u2_l2", "difficulty": "hard", "type": "choice", "prompt": "一个两位数，十位上的数比个位上的数大2，个位是5，这个数读作什么？", "englishAudio": null, "options": ["七十五", "三十五", "五十七"], "answer": "七十五", "explanation": "个位是5，十位比个位大2是7，这个数是75，读作七十五。", "verify": ""}, {"id": "hjm_g1b_u2_l3_q6", "topicId": "hjm_g1b_u2_l3", "difficulty": "medium", "type": "choice", "prompt": "82里面有几个十几个一？", "englishAudio": null, "options": ["8个十、2个一", "2个十、8个一", "8个一、2个十"], "answer": "8个十、2个一", "explanation": "十位上的8表示8个十，个位上的2表示2个一。", "verify": ""}, {"id": "hjm_g1b_u2_l3_q7", "topicId": "hjm_g1b_u2_l3", "difficulty": "hard", "type": "numeric", "prompt": "一个数是7个十，另一个数比它少20，这个数是几？", "englishAudio": null, "options": [], "answer": "50", "explanation": "7个十是70，70少20是50。", "verify": "70-20"}, {"id": "hjm_g1b_u2_l4_q6", "topicId": "hjm_g1b_u2_l4", "difficulty": "medium", "type": "numeric", "prompt": "把48、84、44、40按从小到大排，排在第2个的是几？", "englishAudio": null, "options": [], "answer": "44", "explanation": "从小到大排是40、44、48、84，第2个是44。", "verify": ""}, {"id": "hjm_g1b_u2_l4_q7", "topicId": "hjm_g1b_u2_l4", "difficulty": "hard", "type": "numeric", "prompt": "数轴上，点A是65，点B比点A大8，点C比点B小3，点C是几？", "englishAudio": null, "options": [], "answer": "70", "explanation": "先算点B是65+8=73，再算点C是73-3=70。", "verify": "65+8-3"}, {"id": "hjm_g1b_u2_l5_q6", "topicId": "hjm_g1b_u2_l5", "difficulty": "medium", "type": "numeric", "prompt": "90再添上几是100？", "englishAudio": null, "options": [], "answer": "10", "explanation": "100-90=10，90再添上10就是100。", "verify": "100-90"}, {"id": "hjm_g1b_u2_l5_q7", "topicId": "hjm_g1b_u2_l5", "difficulty": "hard", "type": "numeric", "prompt": "小红有100元，买书用了45元，又买了本子用了25元，还剩几元？", "englishAudio": null, "options": [], "answer": "30", "explanation": "先算100-45=55，再算55-25=30，还剩30元。", "verify": "100-45-25"}, {"id": "hjm_g1b_u2_l6_q6", "topicId": "hjm_g1b_u2_l6", "difficulty": "medium", "type": "numeric", "prompt": "小明有73根小棒，小红有37根，小明比小红多几根？", "englishAudio": null, "options": [], "answer": "36", "explanation": "求多几根用减法：73-37=36根。", "verify": "73-37"}, {"id": "hjm_g1b_u2_l6_q7", "topicId": "hjm_g1b_u2_l6", "difficulty": "hard", "type": "numeric", "prompt": "用3、7、0组成一个最小的两位数是几？", "englishAudio": null, "options": [], "answer": "30", "explanation": "0不能做十位，十位最小是3，个位是0，组成30。", "verify": ""}, {"id": "hjm_g1b_u2_l7_q6", "topicId": "hjm_g1b_u2_l7", "difficulty": "medium", "type": "numeric", "prompt": "与50相邻的数中，比50大的那个再大5是几？", "englishAudio": null, "options": [], "answer": "56", "explanation": "与50相邻且比50大的是51，51再大5是56。", "verify": "50+1+5"}, {"id": "hjm_g1b_u2_l7_q7", "topicId": "hjm_g1b_u2_l7", "difficulty": "hard", "type": "numeric", "prompt": "小明想的数，它前面的数是88，后面的数是90，小明想的数比80大几？", "englishAudio": null, "options": [], "answer": "9", "explanation": "前面是88、后面是90的数是89，89比80大9。", "verify": "89-80"}, {"id": "hjm_g1b_u3_l1_q6", "topicId": "hjm_g1b_u3_l1", "difficulty": "medium", "type": "numeric", "prompt": "小华8时到校，路上要走1小时，他最迟几时从家出发？", "englishAudio": null, "options": [], "answer": "7", "explanation": "到校是8时，往前推1小时，8-1=7时出发。", "verify": "8-1"}, {"id": "hjm_g1b_u3_l1_q7", "topicId": "hjm_g1b_u3_l1", "difficulty": "hard", "type": "numeric", "prompt": "小明的表慢了2小时，表上显示5时，实际是几时？", "englishAudio": null, "options": [], "answer": "7", "explanation": "表慢了，实际时间比表上显示的快2小时：5+2=7时。", "verify": "5+2"}, {"id": "hjm_g1b_u3_l2_q6", "topicId": "hjm_g1b_u3_l2", "difficulty": "medium", "type": "choice", "prompt": "3时半再过1小时是几时半？", "englishAudio": null, "options": ["4时半", "3时", "5时半"], "answer": "4时半", "explanation": "3时半过1小时，时针走1格，是4时半。", "verify": ""}, {"id": "hjm_g1b_u3_l2_q7", "topicId": "hjm_g1b_u3_l2", "difficulty": "hard", "type": "choice", "prompt": "电视节目7时半开始，演了半小时，又重播半小时，全部结束是几时？", "englishAudio": null, "options": ["8时半", "8时", "9时"], "answer": "8时半", "explanation": "7时半过半小时是8时，再过半小时是8时半。", "verify": ""}, {"id": "hjm_g1b_u4_l1_q6", "topicId": "hjm_g1b_u4_l1", "difficulty": "medium", "type": "choice", "prompt": "35+42的得数比70大还是小？", "englishAudio": null, "options": ["比70大", "比70小", "等于70"], "answer": "比70大", "explanation": "35+42=77，77比70大。", "verify": ""}, {"id": "hjm_g1b_u4_l1_q7", "topicId": "hjm_g1b_u4_l1", "difficulty": "hard", "type": "numeric", "prompt": "小红有34颗星星，小明比小红多25颗，两人一共几颗星星？", "englishAudio": null, "options": [], "answer": "93", "explanation": "先算小明有34+25=59颗，再算两人一共59+34=93颗。", "verify": "34+25+34"}, {"id": "hjm_g1b_u4_l2_q6", "topicId": "hjm_g1b_u4_l2", "difficulty": "medium", "type": "choice", "prompt": "下面哪道算式需要进位？", "englishAudio": null, "options": ["34+25", "48+17", "52+30"], "answer": "48+17", "explanation": "48+17个位8+7=15满十，要向十位进1；另外两道个位相加不满十，不用进位。", "verify": ""}, {"id": "hjm_g1b_u4_l2_q7", "topicId": "hjm_g1b_u4_l2", "difficulty": "hard", "type": "numeric", "prompt": "小明算37+25时，先算37+20=57，再算57+5=？", "englishAudio": null, "options": [], "answer": "62", "explanation": "37+25可以拆成先加20得57，再加5得62。", "verify": "57+5"}, {"id": "hjm_g1b_u4_l3_q6", "topicId": "hjm_g1b_u4_l3", "difficulty": "medium", "type": "numeric", "prompt": "16+□+11=40，□是几？", "englishAudio": null, "options": [], "answer": "13", "explanation": "16+11=27，40-27=13，所以□是13。", "verify": "40-16-11"}, {"id": "hjm_g1b_u4_l3_q7", "topicId": "hjm_g1b_u4_l3", "difficulty": "hard", "type": "numeric", "prompt": "19+26+11=？", "englishAudio": null, "options": [], "answer": "56", "explanation": "先算19+11=30凑成整十，再算30+26=56。", "verify": "19+11+26"}, {"id": "hjm_g1b_u5_l1_q6", "topicId": "hjm_g1b_u5_l1", "difficulty": "medium", "type": "choice", "prompt": "小明的跳绳和桌子一样长，小红的跳绳比桌子短，谁的跳绳长？", "englishAudio": null, "options": ["小明", "小红", "一样长"], "answer": "小明", "explanation": "小明的跳绳和桌子一样长，小红的比桌子短，所以小明的跳绳长。", "verify": ""}, {"id": "hjm_g1b_u5_l1_q7", "topicId": "hjm_g1b_u5_l1", "difficulty": "hard", "type": "choice", "prompt": "铅笔比蜡笔长，蜡笔比橡皮长，橡皮比回形针长，最长和最短分别是什么？", "englishAudio": null, "options": ["最长是铅笔，最短是回形针", "最长是蜡笔，最短是橡皮", "最长是铅笔，最短是橡皮"], "answer": "最长是铅笔，最短是回形针", "explanation": "按从长到短排是铅笔、蜡笔、橡皮、回形针，最长是铅笔，最短是回形针。", "verify": ""}, {"id": "hjm_g1b_u5_l2_q6", "topicId": "hjm_g1b_u5_l2", "difficulty": "medium", "type": "numeric", "prompt": "小明估计铅笔长10厘米，实际量是8厘米，估计比实际长几厘米？", "englishAudio": null, "options": [], "answer": "2", "explanation": "估计10厘米，实际8厘米，多了10-8=2厘米。", "verify": "10-8"}, {"id": "hjm_g1b_u5_l2_q7", "topicId": "hjm_g1b_u5_l2", "difficulty": "hard", "type": "numeric", "prompt": "一根绳子分两段，第一段长12厘米，第二段比第一段短4厘米，这根绳子一共长几厘米？", "englishAudio": null, "options": [], "answer": "20", "explanation": "先算第二段长12-4=8厘米，再算一共12+8=20厘米。", "verify": "12+12-4"}, {"id": "hjm_g1b_u5_l3_q6", "topicId": "hjm_g1b_u5_l3", "difficulty": "medium", "type": "numeric", "prompt": "一条线段长5厘米，把它延长3厘米，现在长几厘米？", "englishAudio": null, "options": [], "answer": "8", "explanation": "原来5厘米，延长3厘米，5+3=8厘米。", "verify": "5+3"}, {"id": "hjm_g1b_u5_l3_q7", "topicId": "hjm_g1b_u5_l3", "difficulty": "hard", "type": "numeric", "prompt": "四个点（不在同一条直线上），每两个点连一条线段，一共能连几条线段？", "englishAudio": null, "options": [], "answer": "6", "explanation": "从第一个点连3条，第二个点再连2条新线，第三个点再连1条，3+2+1=6条。", "verify": ""}, {"id": "hjm_g1b_u6_l1_q6", "topicId": "hjm_g1b_u6_l1", "difficulty": "medium", "type": "numeric", "prompt": "小红量窗户：先用拃量了4拃，每拃约10厘米，又用直尺量剩下部分是15厘米，窗户大约长几厘米？", "englishAudio": null, "options": [], "answer": "55", "explanation": "4拃大约4×10=40厘米，再加15厘米，一共55厘米。", "verify": "4*10+15"}, {"id": "hjm_g1b_u6_l1_q7", "topicId": "hjm_g1b_u6_l1", "difficulty": "hard", "type": "numeric", "prompt": "小明一步约50厘米，小红一步约40厘米，两人同时从同一起点走3步，小明比小红多走几厘米？", "englishAudio": null, "options": [], "answer": "30", "explanation": "小明走50×3=150厘米，小红走40×3=120厘米，多150-120=30厘米。", "verify": "50*3-40*3"}, {"id": "hjm_g1b_u6_l2_q6", "topicId": "hjm_g1b_u6_l2", "difficulty": "medium", "type": "numeric", "prompt": "小红一庹约100厘米，她张开双臂量了2次，量出的长度大约几厘米？", "englishAudio": null, "options": [], "answer": "200", "explanation": "一庹约100厘米，量2次大约100×2=200厘米。", "verify": "100*2"}, {"id": "hjm_g1b_u6_l2_q7", "topicId": "hjm_g1b_u6_l2", "difficulty": "hard", "type": "choice", "prompt": "小明一拃8厘米量了5拃，小红一拃10厘米量了4拃，谁量出的绳子长？", "englishAudio": null, "options": ["小明", "小红", "一样长"], "answer": "一样长", "explanation": "小明量出5×8=40厘米，小红量出4×10=40厘米，一样长。", "verify": ""}, {"id": "hjm_g1b_u6_l3_q6", "topicId": "hjm_g1b_u6_l3", "difficulty": "medium", "type": "choice", "prompt": "彩旗按红、红、黄的顺序循环排列，第10面是什么颜色？", "englishAudio": null, "options": ["红", "黄", "蓝"], "answer": "红", "explanation": "每3面一组，第10面是第4组的第1面，是红色。", "verify": ""}, {"id": "hjm_g1b_u6_l3_q7", "topicId": "hjm_g1b_u6_l3", "difficulty": "hard", "type": "numeric", "prompt": "从第1面到第5面一共长16米，相邻两面相隔几米？", "englishAudio": null, "options": [], "answer": "4", "explanation": "从第1面到第5面有4个间隔，16÷4=4米。", "verify": "16/4"}, {"id": "hjm_g1b_u7_l1_q6", "topicId": "hjm_g1b_u7_l1", "difficulty": "medium", "type": "choice", "prompt": "○、△、○、△、○、△，后面一个图形是什么？", "englishAudio": null, "options": ["○", "△", "□"], "answer": "○", "explanation": "图形按○、△重复出现，下一个是○。", "verify": ""}, {"id": "hjm_g1b_u7_l1_q7", "topicId": "hjm_g1b_u7_l1", "difficulty": "hard", "type": "numeric", "prompt": "20、19、17、14、10，后面一个数是几？", "englishAudio": null, "options": [], "answer": "5", "explanation": "每次少的数是1、2、3、4，再少5就是5。", "verify": ""}, {"id": "hjm_g1b_u7_l2_q6", "topicId": "hjm_g1b_u7_l2", "difficulty": "medium", "type": "numeric", "prompt": "数墙底层是1、2、3、4，顶层是几？", "englishAudio": null, "options": [], "answer": "20", "explanation": "第二层是1+2=3、2+3=5、3+4=7，第三层是3+5=8、5+7=12，顶层是8+12=20。", "verify": ""}, {"id": "hjm_g1b_u7_l2_q7", "topicId": "hjm_g1b_u7_l2", "difficulty": "hard", "type": "choice", "prompt": "数墙A底层是3、5、7，数墙B底层是4、5、6，哪座数墙的顶层大？", "englishAudio": null, "options": ["一样大", "数墙A大", "数墙B大"], "answer": "一样大", "explanation": "A顶层是(3+5)+(5+7)=8+12=20，B顶层是(4+5)+(5+6)=9+11=20，一样大。", "verify": ""}, {"id": "hjm_g1a_u1_l1_q8", "topicId": "hjm_g1a_u1_l1", "difficulty": "medium", "type": "numeric", "prompt": "说一说：小明有 7 元，小红比小明少 2 元，两人一共几元？", "englishAudio": null, "options": [], "answer": "12", "explanation": "小红有 7 - 2 = 5 元，两人一共 7 + 5 = 12 元。", "verify": "7+5"}, {"id": "hjm_g1a_u1_l1_q9", "topicId": "hjm_g1a_u1_l1", "difficulty": "hard", "type": "numeric", "prompt": "说一说：盒子里原来有 8 颗糖，吃了 2 颗，又买来 5 颗，送给弟弟 3 颗，再买来 1 颗，现在有几颗？", "englishAudio": null, "options": [], "answer": "9", "explanation": "8 - 2 = 6，6 + 5 = 11，11 - 3 = 8，8 + 1 = 9，现在有 9 颗。", "verify": "8-2+5-3+1"}, {"id": "hjm_g1a_u1_l2_q8", "topicId": "hjm_g1a_u1_l2", "difficulty": "medium", "type": "numeric", "prompt": "玩一玩：小华拍皮球，第一次拍了 5 下，第二次比第一次多拍 3 下，第三次拍了 4 下，一共拍了几下？", "englishAudio": null, "options": [], "answer": "17", "explanation": "第二次拍了 5 + 3 = 8 下，一共 5 + 8 + 4 = 17 下。", "verify": "5+8+4"}, {"id": "hjm_g1a_u1_l2_q9", "topicId": "hjm_g1a_u1_l2", "difficulty": "hard", "type": "numeric", "prompt": "玩一玩：原来有 9 个小朋友玩老鹰捉小鸡，走了 2 个，又来了 4 个，再走 3 个，又来了 1 个，现在有几个小朋友？", "englishAudio": null, "options": [], "answer": "9", "explanation": "9 - 2 = 7，7 + 4 = 11，11 - 3 = 8，8 + 1 = 9，现在有 9 个小朋友。", "verify": "9-2+4-3+1"}, {"id": "hjm_g1a_u1_l3_q8", "topicId": "hjm_g1a_u1_l3", "difficulty": "medium", "type": "numeric", "prompt": "认一认：把 9、2、7、4 按从小到大排，排在第 3 个的是几？", "englishAudio": null, "options": [], "answer": "7", "explanation": "从小到大排是 2、4、7、9，排在第 3 个的是 7。", "verify": ""}, {"id": "hjm_g1a_u1_l3_q9", "topicId": "hjm_g1a_u1_l3", "difficulty": "hard", "type": "choice", "prompt": "认一认：下面哪个数比 6 大 2，又比 10 小？", "englishAudio": null, "options": ["7", "8", "9"], "answer": "8", "explanation": "比 6 大 2 的数是 8，8 比 10 小，符合两个条件。", "verify": ""}, {"id": "hjm_g1a_u2_l1_q8", "topicId": "hjm_g1a_u2_l1", "difficulty": "medium", "type": "numeric", "prompt": "认识立体图形：一个正方体有 8 个顶点，两个正方体一共有几个顶点？", "englishAudio": null, "options": [], "answer": "16", "explanation": "每个正方体 8 个顶点，两个就是 8 + 8 = 16 个。", "verify": "8+8"}, {"id": "hjm_g1a_u2_l1_q9", "topicId": "hjm_g1a_u2_l1", "difficulty": "hard", "type": "choice", "prompt": "认识立体图形：一个圆柱躺着放会滚动，立着放不会滚动；一个球不管怎么放都会滚动。下面哪个说法是对的？", "englishAudio": null, "options": ["圆柱立着放会滚动", "球躺着放不会滚动", "球不管怎么放都会滚动"], "answer": "球不管怎么放都会滚动", "explanation": "球是圆圆的，不管怎么放都会滚动；圆柱只有躺着放才会滚动。", "verify": ""}, {"id": "hjm_g1a_u2_l2_q8", "topicId": "hjm_g1a_u2_l2", "difficulty": "medium", "type": "numeric", "prompt": "认识平面图形：把一个正方形对折两次，能得到几个小正方形？", "englishAudio": null, "options": [], "answer": "4", "explanation": "对折一次得 2 个，再对折一次，每个又分成 2 个，一共 4 个小正方形。", "verify": ""}, {"id": "hjm_g1a_u2_l2_q9", "topicId": "hjm_g1a_u2_l2", "difficulty": "hard", "type": "choice", "prompt": "认识平面图形：用两个一样的三角形可以拼成什么图形？", "englishAudio": null, "options": ["平行四边形", "圆形", "五边形"], "answer": "平行四边形", "explanation": "两个一样的三角形，把对应边对在一起，可以拼成一个平行四边形；只有等腰直角三角形才能拼成正方形，题干没有说明三角形的种类，所以答案是平行四边形。", "verify": ""}, {"id": "hjm_g1a_u3_l1_q8", "topicId": "hjm_g1a_u3_l1", "difficulty": "medium", "type": "numeric", "prompt": "把 5、2、4、1 按从大到小排，排在第 3 个的是几？", "englishAudio": null, "options": [], "answer": "2", "explanation": "从大到小排是 5、4、2、1，排在第 3 个的是 2。", "verify": ""}, {"id": "hjm_g1a_u3_l1_q9", "topicId": "hjm_g1a_u3_l1", "difficulty": "hard", "type": "numeric", "prompt": "1、2、□、4、5，□里填几？再往后数两个数是几？（填最后的数）", "englishAudio": null, "options": [], "answer": "7", "explanation": "□里填 3；从 5 往后数两个数是 6、7，最后的数是 7。", "verify": ""}, {"id": "hjm_g1a_u3_l2_q8", "topicId": "hjm_g1a_u3_l2", "difficulty": "medium", "type": "choice", "prompt": "下面哪个算式的结果是 3？", "englishAudio": null, "options": ["3-3", "0+3", "5-5"], "answer": "0+3", "explanation": "3 - 3 = 0，0 + 3 = 3，5 - 5 = 0，只有 0 + 3 的结果是 3。", "verify": ""}, {"id": "hjm_g1a_u3_l2_q9", "topicId": "hjm_g1a_u3_l2", "difficulty": "hard", "type": "numeric", "prompt": "树上有 5 只鸟，飞走了 5 只，又飞来 2 只，再飞走 2 只，现在有几只？", "englishAudio": null, "options": [], "answer": "0", "explanation": "5 - 5 = 0，0 + 2 = 2，2 - 2 = 0，现在一只也没有了。", "verify": "5-5+2-2"}, {"id": "hjm_g1a_u3_l3_q8", "topicId": "hjm_g1a_u3_l3", "difficulty": "medium", "type": "numeric", "prompt": "7 可以分成 3 和几？这个几再加 1 是几？（填最后的结果）", "englishAudio": null, "options": [], "answer": "5", "explanation": "7 分成 3 和 4，这个 4 再加 1 是 5。", "verify": "7-3+1"}, {"id": "hjm_g1a_u3_l3_q9", "topicId": "hjm_g1a_u3_l3", "difficulty": "hard", "type": "numeric", "prompt": "小明有 9 颗糖，分给弟弟 3 颗，又分给妹妹 2 颗，再买来 4 颗，现在有几颗？", "englishAudio": null, "options": [], "answer": "8", "explanation": "9 - 3 = 6，6 - 2 = 4，4 + 4 = 8，现在有 8 颗。", "verify": "9-3-2+4"}, {"id": "hjm_g1a_u3_l4_q8", "topicId": "hjm_g1a_u3_l4", "difficulty": "medium", "type": "numeric", "prompt": "把 8、6、9、7 按从大到小排，排在第 3 个的是几？", "englishAudio": null, "options": [], "answer": "7", "explanation": "从大到小排是 9、8、7、6，排在第 3 个的是 7。", "verify": ""}, {"id": "hjm_g1a_u3_l4_q9", "topicId": "hjm_g1a_u3_l4", "difficulty": "hard", "type": "numeric", "prompt": "7 后面第三个数是几？再往后数一个是几？（填最后的数）", "englishAudio": null, "options": [], "answer": "11", "explanation": "7 后面第三个数是 10，再往后数一个是 11。", "verify": ""}, {"id": "hjm_g1a_u3_l5_q8", "topicId": "hjm_g1a_u3_l5", "difficulty": "medium", "type": "numeric", "prompt": "一排有 10 个小朋友，从右数第 3 个是小明，从左数小明是第几个？", "englishAudio": null, "options": [], "answer": "8", "explanation": "从右数第 3 个，说明他右边有 2 人，从左数就是 10 - 2 = 8，第 8 个。", "verify": ""}, {"id": "hjm_g1a_u3_l5_q9", "topicId": "hjm_g1a_u3_l5", "difficulty": "hard", "type": "numeric", "prompt": "□ + □