iculty": "basic", "type": "choice", "prompt": "“打扫”的英语单词是？", "englishAudio": "clean", "options": ["clean", "door", "floor"], "answer": "clean", "explanation": "clean 是打扫；door 是门；floor 是地板。", "verify": ""}, {"id": "hje_g1a_u4_l2_q2", "topicId": "hje_g1a_u4_l2", "difficulty": "medium", "type": "choice", "prompt": "想问今天谁值日，应该问？", "englishAudio": "Who's on duty?", "options": ["Who's on duty?", "What's your name?", "How are you?"], "answer": "Who's on duty?", "explanation": "问谁值日用 Who's on duty?，on duty 就是值日。", "verify": ""}, {"id": "hje_g1a_u4_l2_q3", "topicId": "hje_g1a_u4_l2", "difficulty": "hard", "type": "choice", "prompt": "老师说 Clean the blackboard.，是让大家做什么？", "englishAudio": "Clean the blackboard.", "options": ["擦黑板", "开门", "扫地"], "answer": "擦黑板", "explanation": "Clean the blackboard 是擦黑板；clean 是打扫，blackboard 是黑板。", "verify": ""}, {"id": "hje_g1a_u5_l1_q1", "topicId": "hje_g1a_u5_l1", "difficulty": "basic", "type": "choice", "prompt": "“眼睛”的英语单词是？", "englishAudio": "eye", "options": ["eye", "ear", "nose"], "answer": "eye", "explanation": "eye 是眼睛，ear 是耳朵，nose 是鼻子。", "verify": ""}, {"id": "hje_g1a_u5_l1_q2", "topicId": "hje_g1a_u5_l1", "difficulty": "medium", "type": "choice", "prompt": "小朋友指着自己的鼻子，应该说？", "englishAudio": "nose", "options": ["nose", "mouth", "face"], "answer": "nose", "explanation": "nose 是鼻子；mouth 是嘴巴；face 是脸。", "verify": ""}, {"id": "hje_g1a_u5_l1_q3", "topicId": "hje_g1a_u5_l1", "difficulty": "hard", "type": "choice", "prompt": "下面哪个单词表示“耳朵”？", "englishAudio": "ear", "options": ["ear", "eye", "are"], "answer": "ear", "explanation": "ear 是耳朵；eye 是眼睛；are 是“是”，不是身体部位。", "verify": ""}, {"id": "hje_g1a_u5_l2_q1", "topicId": "hje_g1a_u5_l2", "difficulty": "basic", "type": "choice", "prompt": "想介绍“这是我的鼻子”，应该说？", "englishAudio": "This is my nose.", "options": ["This is my nose.", "This is my eye.", "This is my ear."], "answer": "This is my nose.", "explanation": "This is my… 是“这是我的…”，nose 是鼻子。", "verify": ""}, {"id": "hje_g1a_u5_l2_q2", "topicId": "hje_g